window.GRAMMAR = (window.GRAMMAR || []).concat([
  {"id":"d1725293495838","pattern":"〜(よ)うにも〜ない","core":"(よ)うにも〜ない","blankTarget":"ようにも","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"したいけど何らかの理由でできないことを表します。物理的な理由の場合に使いやすいです。 話者の「本当はしたいけどできない」という気持ちを表すのが特徴です。 後件は多くの場合、可能否定形が接続されます。 前件と後件の動詞は同じ動詞を用いることが多いですが、例文（８）のように、別の動詞を接続することもできます。 「言うに言えない」は慣用表現です。 （物理的理由でできない） （心理的理由でできない）","en":"even if one wants to, one cannot; cannot ... no matter how much one wants to","ko":"하려고 해도 할 수 없다; ~하려야 ~할 수 없다"},"formation":{"ja":"動詞意向形＋にも＋動ない形＋ない","en":"動詞意向形＋にも＋動ない形＋ない","ko":"動詞意向形＋にも＋動ない形＋ない"},"examples":[{"ja":"緊張して話しかけようにも話しかけられない。","en":"I'm so nervous that I can't even speak to them, much as I'd like to.","ko":"긴장해서 말을 걸고 싶어도 말을 걸 수가 없다."}],"similar":[]},
  {"id":"d1725293495619","pattern":"〜あっての","core":"あっての","blankTarget":"があっての","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"ＡがなければＢは成り立たないことを表します。 「が」は省略可能です。","en":"only possible because of A; B exists thanks to A","ko":"A가 있기에 비로소 B; A가 있어야 B가 있다"},"formation":{"ja":"名詞Ａ＋あっての＋名詞Ｂ / 名詞＋あってのことだ / 名詞＋があってのことだ","en":"名詞Ａ＋あっての＋名詞Ｂ / 名詞＋あってのことだ / 名詞＋があってのことだ","ko":"名詞Ａ＋あっての＋名詞Ｂ / 名詞＋あってのことだ / 名詞＋があってのことだ"},"examples":[{"ja":"過去があっての現在","en":"The present exists only because of the past.","ko":"과거가 있기에 지금의 현재가 있다."}],"similar":[]},
  {"id":"d1725293495651","pattern":"〜いかんで／いかんでは／いかんによっては","core":"いかんで","blankTarget":"いかんでは","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前件の条件によって結果が変わることを表します。 名詞の後の「の」は省略可。 「いかん」の漢字は「如何」です。 意味は「～次第で（は）」「～次第によっては」とほぼ同じです。","en":"depending on; according to","ko":"~에 따라(서); ~여하에 따라"},"formation":{"ja":"名詞＋（の）＋いかんで / 名詞＋（の）＋いかんでは / 名詞＋（の）＋いかんによっては","en":"名詞＋（の）＋いかんで / 名詞＋（の）＋いかんでは / 名詞＋（の）＋いかんによっては","ko":"名詞＋（の）＋いかんで / 名詞＋（の）＋いかんでは / 名詞＋（の）＋いかんによっては"},"examples":[{"ja":"自分の行動いかんでは人生はそんな悪くない。","en":"Depending on how you act, life isn't so bad.","ko":"자신의 행동 여하에 따라서는 인생은 그렇게 나쁘지 않다."}],"similar":[]},
  {"id":"d1725293495652","pattern":"〜いかんにかかっている／いかんだ／にかかっている","core":"いかんにかかっている","blankTarget":"いかんにかかっている","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"ある事柄が実現するかどうかは、その内容や状態によって決まることを表します。 前件では「～どうか」「～か否か」「どのように～するか」などが呼応することがあります。 この文法は文末に用います。 「いかん」の漢字は「如何」です。 「～次第だ」とほぼ同じ意味です。","en":"depends entirely on; hinges on","ko":"~에 달려 있다; ~여하에 달려 있다"},"formation":{"ja":"名詞＋いかんにかかっている / 名詞＋いかんだ / 名詞＋にかかっている / 文の普通形＋か＋にかかっている / （～にある）","en":"名詞＋いかんにかかっている / 名詞＋いかんだ / 名詞＋にかかっている / 文の普通形＋か＋にかかっている / （～にある）","ko":"名詞＋いかんにかかっている / 名詞＋いかんだ / 名詞＋にかかっている / 文の普通形＋か＋にかかっている / （～にある）"},"examples":[{"ja":"会社が発展していくかどうかは、全社員の働きいかんにかかっている。","en":"Whether the company prospers depends on the efforts of all its employees.","ko":"회사가 발전해 나갈지 어떨지는 전 직원의 노력 여하에 달려 있다."}],"similar":[]},
  {"id":"d1725293495813","pattern":"〜うちに入らない／うちには入らない","core":"うちに入らない","blankTarget":"うちに入らない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"その程度には十分達していないことを表します。「～だとは言えない」とほぼ同義です。","en":"doesn't count as; can hardly be called","ko":"~에 들지 않는다; ~라고 하기엔 한참 부족하다"},"formation":{"ja":"名詞＋のうちに（は）入らない / い形容詞＋うちに（は）入らない / な形容詞＋な＋うちに（は）入らない / 動詞普通形＋うちに（は）入らない","en":"名詞＋のうちに（は）入らない / い形容詞＋うちに（は）入らない / な形容詞＋な＋うちに（は）入らない / 動詞普通形＋うちに（は）入らない","ko":"名詞＋のうちに（は）入らない / い形容詞＋うちに（は）入らない / な形容詞＋な＋うちに（は）入らない / 動詞普通形＋うちに（は）入らない"},"examples":[{"ja":"お酒に強くなったつもりだったが、友人からは「ビール２、３本くらいじゃ飲んだうちに入らない」と言われた。","en":"I thought I had become a tolerant drinker, but a friend told me, \"Two or three beers doesn't even count as drinking.\"","ko":"술이 세졌다고 생각했는데, 친구에게 \"맥주 두세 병 정도로는 마신 것도 아니다\"라는 말을 들었다."}],"similar":[]},
  {"id":"d1725293495639","pattern":"〜が〜だけに","core":"が〜だけに","blankTarget":"が","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"同じ名詞を２度用いて接続し、その性質や状態から考えられる必然的な結果を述べる文型です。 「～のおかげで」「～のせいで」に近い意味を持っています。 後件は良い内容も悪い内容もきます。 後件の内容は、その内容が予測できるような特別な文脈下であれば省略可能です。","en":"precisely because; all the more since","ko":"~인 만큼; ~이기에 더욱"},"formation":{"ja":"名詞＋が＋名詞＋だけに / 名詞＋が＋名詞＋なだけに / 名詞＋が＋名詞＋であるだけに","en":"名詞＋が＋名詞＋だけに / 名詞＋が＋名詞＋なだけに / 名詞＋が＋名詞＋であるだけに","ko":"名詞＋が＋名詞＋だけに / 名詞＋が＋名詞＋なだけに / 名詞＋が＋名詞＋であるだけに"},"examples":[{"ja":"性格が性格なだけに、本音をはっきり言えない。","en":"Given their personality, they can't say what they really think.","ko":"성격이 성격인 만큼 속마음을 똑 부러지게 말하지 못한다."}],"similar":[]},
  {"id":"d1725293495641","pattern":"〜がましい","core":"がましい","blankTarget":"がましい","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"接続された名詞の様子に近いという意味を表します。 通常は良くないことに用いられ、言い訳がましい、差し出がましい、押しつけがましい、恩着せがましい、未練がましい等、接続できる名詞は限られていますので、そのまま単語として覚えたほうが良さそうです。 この表現はいずれも無理やりする、強制するのようなニュアンスを持ちます。","en":"somewhat like; bordering on (often negative)","ko":"~답게 보이는; ~인 체하는 (부정적)"},"formation":{"ja":"名詞＋がましい","en":"名詞＋がましい","ko":"名詞＋がましい"},"examples":[{"ja":"言い訳がましいことは言わないほうがカッコいい。","en":"It's cooler not to sound like you're making excuses.","ko":"변명조의 말을 하지 않는 편이 멋있다."}],"similar":[]},
  {"id":"d1725293495663","pattern":"〜からある／からいる／からする／からの","core":"からある","blankTarget":"からする","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"金額、人数、大きさ、長さ、高さ、重さ、広さ、距離などがおよそその程度であること、あるいはそれ以上であることを表します。「～以上の」とほぼ同じ意味です。 金額の大きさや価値を表す場合は「からする」、人数を表す場合は「からの」「からいる」、それ以外の数量を表す場合は「からある」を用います。（※例外も多少あり） 似た表現に「～もの」があります。「もの」は数量の多さを強調します。 ①３０万からするパソコンを買った。（３０万以上） ②３０万のパソコンを買った。（３０万ちょうど） ③３０万ものパソコンを買った。（”３０万”という金額の高さを強調）","en":"as much as; no less than (emphasizing a large quantity)","ko":"무려 ~이나; ~이상"},"formation":{"ja":"数（＋助数詞）＋からある / 数（＋助数詞）＋からいる / 数（＋助数詞）＋からする / 数（＋助数詞）＋からの","en":"数（＋助数詞）＋からある / 数（＋助数詞）＋からいる / 数（＋助数詞）＋からする / 数（＋助数詞）＋からの","ko":"数（＋助数詞）＋からある / 数（＋助数詞）＋からいる / 数（＋助数詞）＋からする / 数（＋助数詞）＋からの"},"examples":[{"ja":"２００万からする車を買った。","en":"I bought a car that costs at least two million yen.","ko":"200만 엔이나 하는 차를 샀다."}],"similar":[]},
  {"id":"d1725293495664","pattern":"〜からして","core":"からして","blankTarget":"からして","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"ある一部分の要素や事例を見て、全体の状況を捉える文法です。 前件ではまず目につくもの、気づいたものについて述べます。","en":"judging even from; to begin with","ko":"~부터가; ~만 봐도"},"formation":{"ja":"名詞＋からして","en":"名詞＋からして","ko":"名詞＋からして"},"examples":[{"ja":"声とかからしてめっちゃモテそう。","en":"Just from his voice, he seems really popular.","ko":"목소리부터가 엄청 인기 많아 보인다."}],"similar":[]},
  {"id":"d1725293495662","pattern":"〜か否か","core":"か否か","blankTarget":"か否か","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"疑問や判断がしにくいことを表します。「～かどうか」と同じ意味です。 こちらは「～かどうか」よりも比較的硬い表現で、口語での使用頻度はあまり高くないです。","en":"whether or not","ko":"~인지 아닌지; ~여부"},"formation":{"ja":"動詞辞書形／動詞た形＋か否か / い形容詞＋（の）＋か否か / な形容詞語幹＋（である／なの）＋か否か / 名詞＋（である／なの）＋か否か","en":"動詞辞書形／動詞た形＋か否か / い形容詞＋（の）＋か否か / な形容詞語幹＋（である／なの）＋か否か / 名詞＋（である／なの）＋か否か","ko":"動詞辞書形／動詞た形＋か否か / い形容詞＋（の）＋か否か / な形容詞語幹＋（である／なの）＋か否か / 名詞＋（である／なの）＋か否か"},"examples":[{"ja":"人生楽しむか否か。結局は自分次第。","en":"Whether you enjoy life or not comes down to you in the end.","ko":"인생을 즐기는지 아닌지는 결국 자기 하기 나름이다."}],"similar":[]},
  {"id":"d1725293495671","pattern":"〜きっての","core":"きっての","blankTarget":"きっての","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"場所や集団、組織、時代などの名詞に接続し、その範囲内で最も優秀なもの、１番良いものを表します。","en":"the finest in; the leading","ko":"~에서 으뜸가는; ~ 최고의"},"formation":{"ja":"名詞＋きっての","en":"名詞＋きっての","ko":"名詞＋きっての"},"examples":[{"ja":"「清水寺」は京都きっての観光地だ。","en":"Kiyomizu Temple is Kyoto's premier tourist spot.","ko":"'기요미즈데라'는 교토에서 으뜸가는 관광지다."}],"similar":[]},
  {"id":"d1725293495682","pattern":"〜くらいでないと／くらいでなければ／ぐらいでないと／ぐらいでなければ","core":"くらいでないと","blankTarget":"くらいでないと","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前件の程度を満たしていなければ、物事の遂行が困難、不可能、不十分であることを表します。 「～くらいじゃないと／ぐらいじゃないと」は口語で用いられます。","en":"unless it's at least to the extent of","ko":"~정도가 아니면; ~만큼은 아니면"},"formation":{"ja":"名詞＋ぐらいでないと / 動詞普通形＋ぐらいでないと / い形容詞＋ぐらいでないと / な形容詞＋な＋ぐらいでないと","en":"名詞＋ぐらいでないと / 動詞普通形＋ぐらいでないと / い形容詞＋ぐらいでないと / な形容詞＋な＋ぐらいでないと","ko":"名詞＋ぐらいでないと / 動詞普通形＋ぐらいでないと / い形容詞＋ぐらいでないと / な形容詞＋な＋ぐらいでないと"},"examples":[{"ja":"いざとなったら顔でも止めるくらいでないと、ゴールキーパーは務まらない。","en":"Unless you're ready to stop the ball with your face if it comes to that, you can't be a goalkeeper.","ko":"막상 닥치면 얼굴로라도 막을 정도가 아니면 골키퍼를 할 수 없다."}],"similar":[]},
  {"id":"d1725293495683","pattern":"〜くらいなら／ぐらいなら／くらいならむしろ／ぐらいならむしろ","core":"くらいなら","blankTarget":"ぐらいなら","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"二つの物事を比較し、話し手にとって前件よりも後件のほうが望ましいことを表します。 「むしろ」がつくとより強調された表現となります。","en":"rather than; if it means ..., I'd rather","ko":"~할 바에는; ~하느니 차라리"},"formation":{"ja":"動詞辞書形／動ない形＋くらいならむしろ／ぐらいならむしろ～ / 名詞＋くらいならむしろ／ぐらいならむしろ～","en":"動詞辞書形／動ない形＋くらいならむしろ／ぐらいならむしろ～ / 名詞＋くらいならむしろ／ぐらいならむしろ～","ko":"動詞辞書形／動ない形＋くらいならむしろ／ぐらいならむしろ～ / 名詞＋くらいならむしろ／ぐらいならむしろ～"},"examples":[{"ja":"嫌々やるぐらいなら初めからやらないほうがましだ。","en":"If you're going to do it reluctantly, you're better off not doing it at all.","ko":"싫어하면서 할 바에는 차라리 처음부터 하지 않는 편이 낫다."}],"similar":[]},
  {"id":"d1725293495676","pattern":"〜ことこの上ない／この上ない〜／この上なく〜","core":"ことこの上ない","blankTarget":"ことこの上ない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"一種の強調表現です。 それよりも勝るものがないこと、よりよい状態がないこと、既に極限であることを表します。 良いことにも良くないことにも使えます。","en":"extremely; utterly; beyond compare","ko":"더할 나위 없이; 극에 달해"},"formation":{"ja":"な形容詞＋な／である＋ことこの上ない / い形容詞＋ことこの上ない / この上ない＋名詞 / この上なく＋な形容詞／い形容詞","en":"な形容詞＋な／である＋ことこの上ない / い形容詞＋ことこの上ない / この上ない＋名詞 / この上なく＋な形容詞／い形容詞","ko":"な形容詞＋な／である＋ことこの上ない / い形容詞＋ことこの上ない / この上ない＋名詞 / この上なく＋な形容詞／い形容詞"},"examples":[{"ja":"勝負に負け、悔しいことこの上ない。","en":"Having lost the match, I'm more frustrated than words can say.","ko":"승부에서 져서 분하기 그지없다."}],"similar":[]},
  {"id":"d1725293495675","pattern":"〜ことだし","core":"ことだし","blankTarget":"ことだし","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"理由を表します。 前件では根拠になる理由や原因が来て、後件では前件に対する何らかの判断や決定を述べます。 理由は数ある理由のうちの一つで、それ以外の理由の存在も暗示します。","en":"since; what with (one reason among others)","ko":"~기도 하고; ~이기도 하니"},"formation":{"ja":"動詞普通形＋ことだし / い形容詞普通形＋ことだし / な形容詞普通形＋な／である＋ことだし / 名詞＋である＋ことだし","en":"動詞普通形＋ことだし / い形容詞普通形＋ことだし / な形容詞普通形＋な／である＋ことだし / 名詞＋である＋ことだし","ko":"動詞普通形＋ことだし / い形容詞普通形＋ことだし / な形容詞普通形＋な／である＋ことだし / 名詞＋である＋ことだし"},"examples":[{"ja":"熱もあることだし寝ます。","en":"I have a fever and all, so I'll turn in.","ko":"열도 있기도 하니 자겠습니다."}],"similar":[]},
  {"id":"d1725293495678","pattern":"〜ことなく／ことなしに／こともなく","core":"ことなく","blankTarget":"ことなく","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"動作・状態の否定、付帯状況を表します。","en":"without doing; without ever","ko":"~하지 않고; ~함이 없이"},"formation":{"ja":"動詞辞書形＋ことなく / 動詞辞書形＋ことなしに / 動詞辞書形＋こともなく","en":"動詞辞書形＋ことなく / 動詞辞書形＋ことなしに / 動詞辞書形＋こともなく","ko":"動詞辞書形＋ことなく / 動詞辞書形＋ことなしに / 動詞辞書形＋こともなく"},"examples":[{"ja":"気温も湿度も下がることなく、蒸し暑い１日でした。","en":"Neither the temperature nor the humidity dropped, making it a sweltering day.","ko":"기온도 습도도 내려가지 않아 무더운 하루였다."}],"similar":[]},
  {"id":"d1725293495680","pattern":"〜ことのないよう(に)／ことがないよう(に)","core":"ことのないよう(に)","blankTarget":"ことがないよう","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"対策や措置を述べる文法です。 前項の現象や問題が発生しないように、後項で何らかの対策を行います。","en":"so as to ensure there is no; so that ... won't happen","ko":"~하는 일이 없도록"},"formation":{"ja":"動詞辞書形＋ことのないよう（に） / 動詞辞書形＋ことがないよう（に）","en":"動詞辞書形＋ことのないよう（に） / 動詞辞書形＋ことがないよう（に）","ko":"動詞辞書形＋ことのないよう（に） / 動詞辞書形＋ことがないよう（に）"},"examples":[{"ja":"今後一切故障することがないよう、点検に努めます。","en":"We will carry out inspections to ensure no breakdowns occur from now on.","ko":"앞으로 일절 고장이 나는 일이 없도록 점검에 힘쓰겠습니다."}],"similar":[]},
  {"id":"d1725293495677","pattern":"〜こともあって","core":"こともあって","blankTarget":"こともあって","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"理由を表す文法ですが、複数ある原因の中から一つだけ挙げている点が特徴的です。つまり他にも原因があることを暗示します。 多くの場合、後項では何らかの現象の説明がなされます。","en":"partly because; what with","ko":"~하기도 해서; ~인 점도 있어"},"formation":{"ja":"動詞普通形＋こともあって / い形容詞名詞修飾形＋こともあって / な形容詞名詞修飾形＋こともあって / 名詞＋という＋こともあって","en":"動詞普通形＋こともあって / い形容詞名詞修飾形＋こともあって / な形容詞名詞修飾形＋こともあって / 名詞＋という＋こともあって","ko":"動詞普通形＋こともあって / い形容詞名詞修飾形＋こともあって / な形容詞名詞修飾形＋こともあって / 名詞＋という＋こともあって"},"examples":[{"ja":"深夜ということもあって、みんな変なテンションだった。","en":"What with it being late at night, everyone was acting strangely wired.","ko":"심야라는 점도 있어서 다들 이상하게 들떠 있었다."}],"similar":[]},
  {"id":"d1725293495844","pattern":"〜ずには済まない／ないでは済まない／ずには済まされない／ないでは済まされない","core":"ずには済まない","blankTarget":"ないではすまない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"一般常識、社会通念、状況などから鑑みて、必ずそうしなければならないことを表します。 「する」は「せずには済まない」になります。","en":"cannot get away without; must","ko":"~하지 않고는 안 된다; ~하지 않으면 끝나지 않는다"},"formation":{"ja":"動ない形＋ずには済まない / 動ない形＋ないでは済まない","en":"動ない形＋ずには済まない / 動ない形＋ないでは済まない","ko":"動ない形＋ずには済まない / 動ない形＋ないでは済まない"},"examples":[{"ja":"君が悪いのなら謝らないではすまない。","en":"If you're in the wrong, you won't get away without apologizing.","ko":"네가 잘못했으면 사과하지 않고는 안 된다."}],"similar":[]},
  {"id":"d1725293495762","pattern":"〜すら","core":"すら","blankTarget":"すら","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"最低限を表す文法です。 ほとんどの場合良くないことに用います。 最低限のことができない等、対象に対する蔑視や軽視の感情が含まれるのが特徴です。 後件には否定形が呼応します。","en":"even; not even","ko":"~조차; ~마저"},"formation":{"ja":"名詞＋（助詞）＋すら～ない / 動て形＋すら～ない","en":"名詞＋（助詞）＋すら～ない / 動て形＋すら～ない","ko":"名詞＋（助詞）＋すら～ない / 動て形＋すら～ない"},"examples":[{"ja":"体調が悪くて水すら喉を通らない。","en":"I feel so bad that I can't even get water down.","ko":"몸이 안 좋아서 물조차 목을 넘어가지 않는다."}],"similar":[]},
  {"id":"d1725293495759","pattern":"〜そびれる","core":"そびれる","blankTarget":"そびれた","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"すべきことやしようと思っていたことが何らかの理由でできなかったことを表します。","en":"to miss the chance to; to fail to do","ko":"~할 기회를 놓치다; ~하지 못하다"},"formation":{"ja":"動ます形＋そびれる","en":"動ます形＋そびれる","ko":"動ます形＋そびれる"},"examples":[{"ja":"買い物に行きそびれたせいで、冷蔵庫に何もない。","en":"I missed my chance to go shopping, so there's nothing in the fridge.","ko":"장 보러 갈 기회를 놓치는 바람에 냉장고에 아무것도 없다."}],"similar":[]},
  {"id":"d1725293495767","pattern":"〜たいがために／たいがための","core":"たいがために","blankTarget":"たいがために","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「～んがために／んがための」と同じく目的を表します。 「～んがために／んがための」は主に書き言葉で使う硬い表現ですが、「～たいがために／たいがための」はそれよりもやや柔らかいです。 目的達成に対する願望、意志が含まれます。","en":"in order to; out of a desire to","ko":"~하고자; ~하고 싶어서"},"formation":{"ja":"動ます形＋たいがため（に） / 動ます形＋たいがための＋名詞","en":"動ます形＋たいがため（に） / 動ます形＋たいがための＋名詞","ko":"動ます形＋たいがため（に） / 動ます形＋たいがための＋名詞"},"examples":[{"ja":"結果を早く見たいがために映画は倍速にして観る。","en":"I watch movies at double speed because I want to see how they end quickly.","ko":"결과를 빨리 보고 싶어서 영화를 배속으로 본다."}],"similar":[]},
  {"id":"d1725293495765","pattern":"〜たが最後／〜たら最後","core":"たが最後","blankTarget":"たら最後","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前件が発生したら、必ず後件が発生することを表す仮定の文法です。 後件は原則悪いことで、悲劇的、絶望的なことが述べられます。 「最後だ。」などで文が終わる場合があり、後ろは省略することもできます。","en":"once ... happens, there's no going back; once ... then it's the end","ko":"일단 ~하면 끝이다; ~한 이상"},"formation":{"ja":"動た形＋が最後 / 動た形＋ら最後","en":"動た形＋が最後 / 動た形＋ら最後","ko":"動た形＋が最後 / 動た形＋ら最後"},"examples":[{"ja":"行ったら最後、最低３年は帰って来れないだろう。","en":"Once you go, you won't be able to come back for at least three years.","ko":"한번 가면 끝으로, 최소 3년은 돌아오지 못할 것이다."}],"similar":[]},
  {"id":"d1725293495628","pattern":"〜だけましだ／だけまだましだ","core":"だけましだ","blankTarget":"だけまだまし","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"既に良くない状況であることは認めつつも、前項で述べられた程度にとどまって良かった（最小限の被害で済んだ）という意味を表します。 「～だけまだましだ」の「まだ」は強調を表しています。","en":"at least; still better than the worst","ko":"그나마 낫다; ~만 해도 다행이다"},"formation":{"ja":"名詞＋である＋だけましだ / な形容詞語幹＋な／である＋だけましだ / い形容詞普通形＋だけましだ / 動詞普通形＋だけましだ","en":"名詞＋である＋だけましだ / な形容詞語幹＋な／である＋だけましだ / い形容詞普通形＋だけましだ / 動詞普通形＋だけましだ","ko":"名詞＋である＋だけましだ / な形容詞語幹＋な／である＋だけましだ / い形容詞普通形＋だけましだ / 動詞普通形＋だけましだ"},"examples":[{"ja":"確かに暑いが、湿度が高くないだけまだましだ。","en":"It's hot for sure, but at least the humidity is low, so it's bearable.","ko":"확실히 덥지만 습도가 높지 않은 것만 해도 그나마 낫다."}],"similar":[]},
  {"id":"d1725293495775","pattern":"〜たつもりはない／たつもりではない／たつもりはなかった","core":"たつもりはない","blankTarget":"たつもりはありません","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"過去の行為によって引き起こされた相手の勘違いや誤解に対する説明・弁明を表します。","en":"didn't mean to; had no intention of having done","ko":"~할 생각은 없었다; ~한 게 아니다"},"formation":{"ja":"動た形＋つもりはない / 動た形＋つもりはなかった","en":"動た形＋つもりはない / 動た形＋つもりはなかった","ko":"動た形＋つもりはない / 動た形＋つもりはなかった"},"examples":[{"ja":"そんなこと言ったつもりはありませんよ。","en":"I didn't mean to say anything like that.","ko":"그런 말을 할 생각은 없었습니다."}],"similar":[]},
  {"id":"d1725293495630","pattern":"〜だにしない","core":"だにしない","blankTarget":"だにしなかった","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「～さえしない」「～さえ～ない」と同じ意味です。 「夢にだに思わなかった」は慣用表現です。 微動、予想、想像、一顧などの限られた語につきます。","en":"not even; without so much as","ko":"~조차 하지 않다; ~할 생각도 않다"},"formation":{"ja":"名詞＋だに","en":"名詞＋だに","ko":"名詞＋だに"},"examples":[{"ja":"母が倒れたと聞いても、彼は微動だにしなかった。","en":"Even after hearing that his mother had collapsed, he didn't stir an inch.","ko":"어머니가 쓰러졌다는 말을 듣고도 그는 꿈쩍도 하지 않았다."}],"similar":[]},
  {"id":"d1725293495631","pattern":"〜だの〜だの(と)","core":"だの〜だの(と)","blankTarget":"だの","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"何らかの共通項を持った要素たちの中からいくつかを列挙する一部列挙型の並列助詞です。他の要素の存在も暗示します。 多くの場合、列挙した事物に対する嫌悪感や不快感、敵意などのネガティブなニュアンスが含まれます。 通常は２つの要素を列挙しますが、３つ以上挙げることも可能です。また２つ目の要素は省略することもできます。その場合は「～だの何だの（と）」という慣用的な言い方を用います。","en":"and whatnot; this and that (often disparaging)","ko":"~라느니 ~라느니; ~니 ~니 하며"},"formation":{"ja":"名詞＋だの＋名詞＋だの（と） / ナ形容詞語幹＋だの＋ナ形容詞語幹＋だの（と） / イ形容詞普通形＋だの＋イ形容詞普通形＋だの（と） / 動詞普通形＋だの＋動詞普通形＋だの（と） / 会話文＋だの会話文＋だの（と）","en":"名詞＋だの＋名詞＋だの（と） / ナ形容詞語幹＋だの＋ナ形容詞語幹＋だの（と） / イ形容詞普通形＋だの＋イ形容詞普通形＋だの（と） / 動詞普通形＋だの＋動詞普通形＋だの（と） / 会話文＋だの会話文＋だの（と）","ko":"名詞＋だの＋名詞＋だの（と） / ナ形容詞語幹＋だの＋ナ形容詞語幹＋だの（と） / イ形容詞普通形＋だの＋イ形容詞普通形＋だの（と） / 動詞普通形＋だの＋動詞普通形＋だの（と） / 会話文＋だの会話文＋だの（と）"},"examples":[{"ja":"霊能者とか大嫌いだ。守護霊の言葉だの除霊だのと変なことばかり言うから。","en":"I hate psychics. They're always going on about guardian spirits and exorcisms and other weird stuff.","ko":"영능자 같은 건 정말 싫다. 수호령의 말이라느니 퇴마라느니 이상한 소리만 하니까."}],"similar":[]},
  {"id":"d1725293495770","pattern":"〜たら〜たで／〜ば〜で","core":"たら〜たで","blankTarget":"たら","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"２つの対立した物事を挙げ、どちらであっても同じであることを表す文型です。 同じ形式の過去形を２度使って接続します。 過去形に接続することが多いです。","en":"if so, then that's its own problem too; either way it's trouble","ko":"~하면 ~대로; ~라면 ~대로"},"formation":{"ja":"～だったら～だったで（後件省略可） / ～たら～たで / ～なら～で / ～れば～で","en":"～だったら～だったで（後件省略可） / ～たら～たで / ～なら～で / ～れば～で","ko":"～だったら～だったで（後件省略可） / ～たら～たで / ～なら～で / ～れば～で"},"examples":[{"ja":"「はい」って言いながら聞いていたら「ちゃんと聞いてるのか」と怒られるし、何か言ったら言ったで「口答えするな」って怒られるし、どうしたらいいか分からない。","en":"When I listen while saying \"yes,\" I get scolded for not really listening; if I say something, I get scolded for talking back. I don't know what to do.","ko":"\"네\"라고 하면서 듣고 있으면 제대로 듣냐고 혼나고, 뭐라도 말하면 말대꾸하지 말라고 혼나고, 어떻게 해야 할지 모르겠다."}],"similar":[]},
  {"id":"d1725293495771","pattern":"〜たら〜ところだ","core":"たら〜ところだ","blankTarget":"たら","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"実際には起こらなかったことを、もし起こっていればどうなっていたかということを述べる反事実条件を表します。 前件に「～ば」「～たら」「～なら」等の条件文が来ます。","en":"if ... it would have been; in that case it would have","ko":"~했더라면 ~했을 것이다"},"formation":{"ja":"動詞辞書形＋ところだ / 動た形＋ところだ","en":"動詞辞書形＋ところだ / 動た形＋ところだ","ko":"動詞辞書形＋ところだ / 動た形＋ところだ"},"examples":[{"ja":"一国の主を批判する行為は、昔だったら処刑されているところだ。","en":"Criticizing the head of a nation would have gotten you executed in the past.","ko":"한 나라의 주인을 비판하는 행위는 옛날이었다면 처형되었을 것이다."}],"similar":[]},
  {"id":"d1725293495768","pattern":"〜たらしい／ったらしい","core":"たらしい","blankTarget":"ったらしい","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"接続する語の様子、その程度が度を越えて嫌悪感に達したときに用いられる表現です。良くないことに用いられます。 決まった語につき、接続できるものは多くありません。","en":"annoyingly ...-ish; reeking of","ko":"~스러운; ~답게 보이는 (못마땅함)"},"formation":{"ja":"名詞＋たらしい／ったらしい / い形容詞語幹＋たらしい／ったらしい / な形容詞語幹＋たらしい／ったらしい","en":"名詞＋たらしい／ったらしい / い形容詞語幹＋たらしい／ったらしい / な形容詞語幹＋たらしい／ったらしい","ko":"名詞＋たらしい／ったらしい / い形容詞語幹＋たらしい／ったらしい / な形容詞語幹＋たらしい／ったらしい"},"examples":[{"ja":"嫌みったらしいことばかり言っていると、友達は減っていくばかりだ。","en":"If you keep making snide remarks, you'll just keep losing friends.","ko":"비꼬는 투로 말만 하면 친구는 줄어들기만 한다."}],"similar":[]},
  {"id":"d1725293495769","pattern":"〜たらそれまでだ／ばそれまでだ／たらそれまでのことだ／ばそれまでのことだ／はそれまでだ","core":"たらそれまでだ","blankTarget":"らそれまでのこと","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"仮定条件文の後ろにつき、物事が限界に達すること、終わることを表します。 「もしそうなったら終わりだ」という意味ですが、終わりが来ることに対して残念な気持ちはなく、それを悪く捉えることもありません。 話者の楽観視、納得の諦め、ふっきれた様子を表すことができる文型です。","en":"if that happens, then that's that; then it's simply over","ko":"그렇게 되면 그걸로 끝이다; 그뿐이다"},"formation":{"ja":"動た形＋ら＋それまで（のこと）だ / 動ば形＋それまで（のこと）だ / ～ならそれまで（のこと）だ / ～たらそれまで（のこと）だ / ～ればそれまで（のこと）だ","en":"動た形＋ら＋それまで（のこと）だ / 動ば形＋それまで（のこと）だ / ～ならそれまで（のこと）だ / ～たらそれまで（のこと）だ / ～ればそれまで（のこと）だ","ko":"動た形＋ら＋それまで（のこと）だ / 動ば形＋それまで（のこと）だ / ～ならそれまで（のこと）だ / ～たらそれまで（のこと）だ / ～ればそれまで（のこと）だ"},"examples":[{"ja":"「ご縁」が恋愛を決める。勇気を出して告白をし想いを伝えましょう。断られたらそれまでのこと。","en":"Fate decides romance. Summon your courage, confess, and tell them how you feel. If you're rejected, that's the end of it.","ko":"인연이 연애를 결정한다. 용기를 내서 고백하고 마음을 전하자. 거절당하면 그걸로 끝이다."}],"similar":[]},
  {"id":"d1725293495772","pattern":"〜たりとも〜ない","core":"たりとも〜ない","blankTarget":"たりとも","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「たりとも」の前には１日、１人、１秒などの「１＋助数詞」の形が接続され、後件に必ず否定が伴います。 「～さえも～ない」とほぼ同義で、特に数量が少ないことを強調する文型です。 命令や禁止にもよく使われます。 「何人（なんぴと／なんびと）」は慣用句。","en":"not even one; not a single","ko":"단 ~조차도 ~않다; ~만큼도 ~않다"},"formation":{"ja":"１＋助数詞＋たりとも～ない","en":"１＋助数詞＋たりとも～ない","ko":"１＋助数詞＋たりとも～ない"},"examples":[{"ja":"渋滞で１ｍｍたりとも進まない。","en":"Caught in traffic, we aren't moving even a millimeter.","ko":"정체 때문에 1밀리미터도 나아가지 않는다."}],"similar":[]},
  {"id":"d1725293495773","pattern":"〜たるもの／〜たる〜／〜たるに","core":"たるもの","blankTarget":"たるもの","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「たる」は立場を表します。「～たるもの」は「～として」、「～たる～」は「～としての～」という意味です。 「たる」の前には職業や立場を表す名詞が接続されます。 後件には「～するべき」「～しなければならない」「～してはいけない」などが呼応し、その職業や立場の人はこうするべきだと釘を刺す言い方です。 「～たるに」は後件に「値する」や「ふさわしい」などが来ることが多く、「～としての基準を満たしている」という意味を表します。","en":"as a true ...; one who is a ... ought to","ko":"~된 자로서; ~인 사람이라면"},"formation":{"ja":"名詞＋たるもの（たる者） / 名詞＋たる＋名詞 / ～たるに値する","en":"名詞＋たるもの（たる者） / 名詞＋たる＋名詞 / ～たるに値する","ko":"名詞＋たるもの（たる者） / 名詞＋たる＋名詞 / ～たるに値する"},"examples":[{"ja":"医者たるもの、患者を第一に考えるべきだ。","en":"A doctor should put the patient first.","ko":"의사된 자로서 환자를 첫째로 생각해야 한다."}],"similar":[]},
  {"id":"d1725293495632","pattern":"〜だろうに","core":"だろうに","blankTarget":"だろうに","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"意味は２つあります。 ①他人の行為や境遇に対する話し手の同情を表します。 後項ではそれに対する評価が述べられますが、省略することができます。 ②やるべきことをしなかったことや、実際に起きなかったこと（事実に反する仮想）に対する残念な気持ちを表します。 後項は省略することができます。","en":"surely ... and yet; if only (expressing sympathy or regret)","ko":"~일 텐데; ~했을 텐데 (안타까움)"},"formation":{"ja":"文の普通形＋だろうに","en":"文の普通形＋だろうに","ko":"文の普通形＋だろうに"},"examples":[{"ja":"時間なんてたくさんあるだろうに、有効に使わない人こそ少ないと嘆く。","en":"There's surely plenty of time, yet I lament that so few people use it effectively.","ko":"시간은 얼마든지 있을 텐데, 그것을 효과적으로 쓰는 사람이 적다고 한탄한다."}],"similar":[]},
  {"id":"d1725293495766","pattern":"〜た弾みに／弾みで／た拍子に／拍子で","core":"た弾みに","blankTarget":"た拍子に","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前項が引き金となって（きっかけとなって）、後項の事態が偶発的に発生することを表します。この文型における「弾み」と「拍子」は、瞬間的な勢いやきっかけを意味します。 通常は人が不注意で、あるいはうっかりして起きた現象を述べるときに用います。 「その弾みに」「その拍子に」「何かの拍子に」などの言い方もあります。","en":"in the split second that; just as (something happened)","ko":"~한 탄에; ~한 순간"},"formation":{"ja":"動た形＋弾みに / 動た形＋拍子に","en":"動た形＋弾みに / 動た形＋拍子に","ko":"動た形＋弾みに / 動た形＋拍子に"},"examples":[{"ja":"寝起きによろけた拍子に、足首をひねって痛めた。","en":"I twisted my ankle when I stumbled just after waking up.","ko":"자다 일어나 비틀거린 탄에 발목을 접질려 다쳤다."}],"similar":[]},
  {"id":"d1725293495756","pattern":"〜っぱなし","core":"っぱなし","blankTarget":"っぱなし","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"２つの意味があります。 ①本来すべきことを放置して、その状態が持続していること ②ある状態が持続していること いずれの場合も話者の物事に対するマイナスのニュアンスがありますので、良くないことに使う場合が多いです。 最近では「ゴルフの打ちっぱなし」「歌いっぱなし」みたいに、「～放題」と同じような使い方もあります。この場合は悪いニュアンスはありません。","en":"left as is; kept ...ing; doing ... nonstop","ko":"~한 채로 내버려두다; 계속 ~만 하다"},"formation":{"ja":"動ます形＋っぱなし","en":"動ます形＋っぱなし","ko":"動ます形＋っぱなし"},"examples":[{"ja":"車に鍵を差しっぱなしで買い物に行ってしまった。","en":"I left the key in the car and went off shopping.","ko":"차에 열쇠를 꽂아 둔 채로 장을 보러 가 버렸다."}],"similar":[]},
  {"id":"d1725293495783","pattern":"〜てしかるべきだ","core":"てしかるべきだ","blankTarget":"てしかるべき","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「～するのが当然」という意味を表します。 硬い表現で、話し言葉の場合は「当然」や「当たり前」と言い換えて話されます。 「しかるべき＋名詞」という形で連体詞的な使い方をすると、「相応しい」という意味になります。","en":"should; ought to; it is only proper that","ko":"마땅히 ~해야 한다"},"formation":{"ja":"動て形＋しかるべきだ / い形容詞て形＋しかるべきだ","en":"動て形＋しかるべきだ / い形容詞て形＋しかるべきだ","ko":"動て形＋しかるべきだ / い形容詞て形＋しかるべきだ"},"examples":[{"ja":"女性は料理ができてしかるべきという考え方は古い。","en":"The idea that women ought to be able to cook is outdated.","ko":"여성은 마땅히 요리를 할 수 있어야 한다는 생각은 낡았다."}],"similar":[]},
  {"id":"d1725293495638","pattern":"〜でなくてなんだろう","core":"でなくてなんだろう","blankTarget":"でなくてなんだろうか","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"強調の文型です。それ以外ではなく、まさしくそれであるという意味を表します。 「～が～でなくてなんだろう（か）」という文型でよく使います。 「一体」が呼応することがあります。","en":"if that isn't ... then what is; what else could it be but","ko":"~이 아니고 무엇이겠는가; 바로 ~이다"},"formation":{"ja":"名詞＋でなくてなんだろう（か） / 名詞＋でなくてなんであろう（か） / ※イ形容詞語幹＋くなくてなんだろう（か） / ※イ形容詞語幹＋くなくてなんであろう（か）","en":"名詞＋でなくてなんだろう（か） / 名詞＋でなくてなんであろう（か） / ※イ形容詞語幹＋くなくてなんだろう（か） / ※イ形容詞語幹＋くなくてなんであろう（か）","ko":"名詞＋でなくてなんだろう（か） / 名詞＋でなくてなんであろう（か） / ※イ形容詞語幹＋くなくてなんだろう（か） / ※イ形容詞語幹＋くなくてなんであろう（か）"},"examples":[{"ja":"激しく続くこの腹痛がいったい病気でなくてなんだろうか。","en":"What could this severe, persistent stomachache be if not an illness?","ko":"심하게 계속되는 이 복통이 도대체 병이 아니고 무엇이겠는가."}],"similar":[]},
  {"id":"d1725293495777","pattern":"〜ては〜ては〜／〜ては〜、〜ては〜","core":"ては〜ては〜","blankTarget":"ては","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"連続する動作を表す動詞を用い接続します。その動作が繰り返し行われることを表します。 動詞の順序はお互いに変えることができます。 「～ちゃ～、～ちゃ～」「～じゃ～、～じゃ～」は口語です。","en":"doing ... and ... over and over","ko":"~했다 ~했다 하며; ~하기를 거듭하며"},"formation":{"ja":"動て形＋は～、動て形＋は～","en":"動て形＋は～、動て形＋は～","ko":"動て形＋は～、動て形＋は～"},"examples":[{"ja":"結婚しては離婚し、離婚しては結婚し。","en":"Marrying and divorcing, divorcing and marrying again.","ko":"결혼했다 이혼했다, 이혼했다 결혼했다 하며."}],"similar":[]},
  {"id":"d1725293495634","pattern":"〜ではあるまいし／でもあるまいし／じゃあるまいし","core":"ではあるまいし","blankTarget":"じゃあるまいし","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"原因や理由を表します。 後件では相手に対する忠告やアドバイス、命令、批判、話者の判断を述べます。しばしば非難するニュアンスが含まれるため、目上の人に使いにくいです。 口語ではよく「～じゃあるまいし」が使われます。 後件は省略されて、「～ではあるまいし」で終わることもあります。 「子供ではあるまいし」「減るものじゃあるまいし」「減るもんじゃあるまいし」はよく用いられる表現です。 「あるまい」は否定推量「ないだろう」の意。","en":"it's not as if ...; you're hardly a ...","ko":"~도 아닌데; ~인 것도 아닌데"},"formation":{"ja":"動詞辞書形＋ん＋ではあるまいし／でもあるまいし／じゃあるまいし / 動詞辞書形＋わけ＋ではあるまいし／でもあるまいし／じゃあるまいし / 動た形＋ん＋ではあるまいし／でもあるまいし／じゃあるまいし / 動た形＋わけ＋ではあるまいし／でもあるまいし／じゃあるまいし / 名詞＋ではあるまいし／でもあるまいし／じゃあるまいし","en":"動詞辞書形＋ん＋ではあるまいし／でもあるまいし／じゃあるまいし / 動詞辞書形＋わけ＋ではあるまいし／でもあるまいし／じゃあるまいし / 動た形＋ん＋ではあるまいし／でもあるまいし／じゃあるまいし / 動た形＋わけ＋ではあるまいし／でもあるまいし／じゃあるまいし / 名詞＋ではあるまいし／でもあるまいし／じゃあるまいし","ko":"動詞辞書形＋ん＋ではあるまいし／でもあるまいし／じゃあるまいし / 動詞辞書形＋わけ＋ではあるまいし／でもあるまいし／じゃあるまいし / 動た形＋ん＋ではあるまいし／でもあるまいし／じゃあるまいし / 動た形＋わけ＋ではあるまいし／でもあるまいし／じゃあるまいし / 名詞＋ではあるまいし／でもあるまいし／じゃあるまいし"},"examples":[{"ja":"子供じゃあるまいし、身の回りの事は自分でやりなさい。","en":"You're not a child anymore, so take care of your own affairs.","ko":"아이도 아닌데, 자기 주변 일은 스스로 하렴."}],"similar":[]},
  {"id":"d1725293495635","pattern":"〜では済まない／では済まされない","core":"では済まない","blankTarget":"では済まされない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前件の状態では問題を解決するに至らないこと、あるいはそれ自体が許されないことを表します。主に批判、非難に用います。","en":"won't be settled by; won't stop at; won't be forgiven as","ko":"~로는 끝나지 않는다; ~해서는 안 된다"},"formation":{"ja":"名詞＋では済まない／では済まされない / 動詞普通形＋（の）では済まない／（の）では済まされない / 発話文＋では済まない／では済まされない","en":"名詞＋では済まない／では済まされない / 動詞普通形＋（の）では済まない／（の）では済まされない / 発話文＋では済まない／では済まされない","ko":"名詞＋では済まない／では済まされない / 動詞普通形＋（の）では済まない／（の）では済まされない / 発話文＋では済まない／では済まされない"},"examples":[{"ja":"会社の金を横領すれば、懲戒免職では済まされないぞ。","en":"If you embezzle company funds, a disciplinary dismissal won't be the end of it.","ko":"회사 돈을 횡령하면 징계 면직으로는 끝나지 않는다."}],"similar":[]},
  {"id":"d1725293495776","pattern":"〜ては敵わない(かなわない)／ては遣り切れない(やりきれない)","core":"ては敵わない(かなわない)","blankTarget":"てかなわない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"我慢できない、耐えられないという主観的な感情を強調します。 「やりきれない」は例文（８）のように単独でも用いることができます。 「こんなに」等の語が呼応すると、「～ては敵わない／ては遣り切れない」のように「は」が必要になる場合が多いです。 元々は動詞「（に）適う／敵わない」です。対抗する力がある／ないといいう意味を持ちます。例文（９）（10）。","en":"unbearable; impossible to put up with","ko":"~해서는 견딜 수 없다; ~하곤 못 배긴다"},"formation":{"ja":"動て形＋（は）かなわない / イ形語幹＋くて（は）かなわない / ナ形語幹＋で（は）かなわない / 名詞＋で（は）かなわない","en":"動て形＋（は）かなわない / イ形語幹＋くて（は）かなわない / ナ形語幹＋で（は）かなわない / 名詞＋で（は）かなわない","ko":"動て形＋（は）かなわない / イ形語幹＋くて（は）かなわない / ナ形語幹＋で（は）かなわない / 名詞＋で（は）かなわない"},"examples":[{"ja":"歯が痛くてかなわない。","en":"My toothache is unbearable.","ko":"이가 아파서 견딜 수가 없다."}],"similar":[]},
  {"id":"d1725293495779","pattern":"〜てみせる","core":"てみせる","blankTarget":"てみせて","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"他の人に理解してもらうためにお手本を示すことを表します。 この用法はＮ３レベルです。","en":"to show (how); to demonstrate","ko":"~해 보이다; ~하는 걸 보여 주다"},"formation":{"ja":"動て形＋見せる","en":"動て形＋見せる","ko":"動て形＋見せる"},"examples":[{"ja":"やり方が分からないので、一度やってみせてくれませんか？","en":"I don't know how to do it, so could you show me once?","ko":"하는 방법을 모르겠으니 한 번 해 보여 주시겠어요?"}],"similar":[]},
  {"id":"d1725293495636","pattern":"〜でもあり〜でもある","core":"でもあり〜でもある","blankTarget":"でもあり","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"人物や事柄に同時に２つの性質があることを述べる文型です。 「～でもあり、また～でもある」のように、「また」が呼応することもあります。","en":"is both ... and ...; is ... as well as ...","ko":"~이기도 하고 ~이기도 하다"},"formation":{"ja":"名詞＋でもあり＋名詞＋でもある / い形容詞語幹＋くもあり＋い形容詞語幹＋くもある / な形容詞語幹＋でもあり＋な形容詞語幹＋でもある","en":"名詞＋でもあり＋名詞＋でもある / い形容詞語幹＋くもあり＋い形容詞語幹＋くもある / な形容詞語幹＋でもあり＋な形容詞語幹＋でもある","ko":"名詞＋でもあり＋名詞＋でもある / い形容詞語幹＋くもあり＋い形容詞語幹＋くもある / な形容詞語幹＋でもあり＋な形容詞語幹＋でもある"},"examples":[{"ja":"あと１週間働けば今年も終わり。年末年始の休みが楽しみでもあり、仕事始めが怖くもある。","en":"One more week of work and this year is over. I'm looking forward to the New Year holiday and also dreading the first day back.","ko":"일주일만 더 일하면 올해도 끝이다. 연말연시 휴가가 기대되기도 하고, 일 시작이 두렵기도 하다."}],"similar":[]},
  {"id":"d1725293495780","pattern":"〜てもどうにもならない／てもどうなるものでもない","core":"てもどうにもならない","blankTarget":"てもどうにもならない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前件の状態や動作では、問題の解決には至らないことを表します。 単に「どうにもならない」でも同じ意味です。例文（８）。","en":"even if ..., nothing can be done; it won't help","ko":"~해도 어쩔 수 없다; ~해 봤자 소용없다"},"formation":{"ja":"動て形＋も＋どうにもならない／どうなるものでもない / 名詞＋でも＋どうにもならない／どうなるものでもない / ナ形語幹＋でも＋どうにもならない／どうなるものでもない / イ形語幹＋くても＋＋どうにもならない／どうなるものでもない","en":"動て形＋も＋どうにもならない／どうなるものでもない / 名詞＋でも＋どうにもならない／どうなるものでもない / ナ形語幹＋でも＋どうにもならない／どうなるものでもない / イ形語幹＋くても＋＋どうにもならない／どうなるものでもない","ko":"動て形＋も＋どうにもならない／どうなるものでもない / 名詞＋でも＋どうにもならない／どうなるものでもない / ナ形語幹＋でも＋どうにもならない／どうなるものでもない / イ形語幹＋くても＋＋どうにもならない／どうなるものでもない"},"examples":[{"ja":"過去の「もし」を考えてもどうにもならない。","en":"There's no point dwelling on the \"what ifs\" of the past.","ko":"과거의 \"만약\"을 생각해 봤자 아무 소용없다."}],"similar":[]},
  {"id":"d1725293495637","pattern":"〜でも何でもない／くも何ともない","core":"でも何でもない","blankTarget":"でも何でもない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"強い否定を表し、良い事にも悪い事にも使えます。 人や物事に対する評価によく用います。","en":"not at all; nothing like; not in the least","ko":"전혀 …이 아니다; …따위가 아니다"},"formation":{"ja":"名詞＋でも何でもない / な形容詞語幹＋でも何でもない / い形容詞語幹＋くも何ともない","en":"名詞＋でも何でもない / な形容詞語幹＋でも何でもない / い形容詞語幹＋くも何ともない","ko":"名詞＋でも何でもない / な形容詞語幹＋でも何でもない / い形容詞語幹＋くも何ともない"},"examples":[{"ja":"誕生日でも何でもないのにプレゼントをもらった。","en":"I got a present even though it wasn't my birthday or anything special.","ko":"생일도 아닌데 선물을 받았다."}],"similar":[]},
  {"id":"d1725293495781","pattern":"〜ても差し支えない(さしつかえない)","core":"ても差し支えない(さしつかえない)","blankTarget":"ても","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"消極的な許可・許容を表します。 比較的硬い表現なので、正式な場面で使われることが多いです。 意味の同じ「～ても構わない」はこれよりも柔らかい表現です。","en":"it is fine to...; there is no problem even if...","ko":"…해도 지장 없다; …해도 괜찮다"},"formation":{"ja":"動て形＋も差し支えない / い形容詞語幹＋くて＋も差し支えない / な形容詞語幹＋で＋も差し支えない / 名詞＋で＋も差し支えない","en":"動て形＋も差し支えない / い形容詞語幹＋くて＋も差し支えない / な形容詞語幹＋で＋も差し支えない / 名詞＋で＋も差し支えない","ko":"動て形＋も差し支えない / い形容詞語幹＋くて＋も差し支えない / な形容詞語幹＋で＋も差し支えない / 名詞＋で＋も差し支えない"},"examples":[{"ja":"年賀状などあってもなくても全く差し支えない。","en":"Whether or not there are New Year's cards makes no difference at all.","ko":"연하장 같은 건 있어도 없어도 전혀 상관없다."}],"similar":[]},
  {"id":"d1725293495782","pattern":"〜ても知らない","core":"ても知らない","blankTarget":"ても知らない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"相手に対する警告や忠告を表します。 相手がある状態を継続し続けると何らかの重大な問題が発生するときに使い、警告しつつもやや突き放したようなニュアンスが含まれます。 多くの場合は後ろには「よ」「ぞ」「から」「からね」などの終助詞がつきます。","en":"if you keep doing that, don't expect me to care; you're on your own","ko":"…해도 나는 모른다; …하다가 문제가 생겨도 책임 못 진다"},"formation":{"ja":"動て形＋も知らない＋（終助詞）","en":"動て形＋も知らない＋（終助詞）","ko":"動て形＋も知らない＋（終助詞）"},"examples":[{"ja":"こんな時間まで起きていて、明日朝起きれなくても知らないよ。","en":"Staying up this late and unable to get up tomorrow morning? Don't say I didn't warn you.","ko":"이렇게 늦게까지 안 자고 있다가 내일 아침에 못 일어나도 나는 모른다."}],"similar":[]},
  {"id":"d1725293495786","pattern":"〜てやる","core":"てやる","blankTarget":"てやる","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"強い感情に突き動かされて何かをすることを表します。 意志、意欲、やる気、野心、野望、熱意、使命感、覚悟、決心、怒り、不満など… この文型の本質は「相手にとって不利益となる行為をしてあげる」という行為の授受です。 「あげる」よりもぞんざいな言い方である「やる」を使うことで、相手に対する強い感情を表すことができます。","en":"do something for someone (bluntly); I'll show them (with strong resolve)","ko":"…해 주다(거친 말투); 반드시 …해 주겠다"},"formation":{"ja":"動て形＋やる","en":"動て形＋やる","ko":"動て形＋やる"},"examples":[{"ja":"もっと上手になってあいつを見返してやる！","en":"I'll get better and show that guy!","ko":"더 잘해서 그 녀석을 한 번 눌러 주겠다!"}],"similar":[]},
  {"id":"d1725293495784","pattern":"〜て済むことではない／で済むことではない／て済む問題ではない／で済む問題ではない","core":"て済むことではない","blankTarget":"て済むことではない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"その程度では不十分で、問題を解決するには至らないことを表します。主に批判、非難に用います。 「【Ｎ１文法】～では済まない／では済まされない」よりも、程度の不十分さがより強調される文型です。","en":"not something that can be settled by...; not just a matter of...","ko":"…하는 것으로 끝날 문제가 아니다; …만으로 해결될 일이 아니다"},"formation":{"ja":"動て形＋済むことではない／済む問題ではない / 名詞＋で済むことではない／済む問題ではない / 発話文＋で済むことではない／済む問題ではない","en":"動て形＋済むことではない／済む問題ではない / 名詞＋で済むことではない／済む問題ではない / 発話文＋で済むことではない／済む問題ではない","ko":"動て形＋済むことではない／済む問題ではない / 名詞＋で済むことではない／済む問題ではない / 発話文＋で済むことではない／済む問題ではない"},"examples":[{"ja":"何でも謝って済むことではないけれど、謝れない人間は最低だ。","en":"Not everything can be settled with an apology, but someone who can't apologize is the worst.","ko":"뭐든 사과하면 끝날 문제는 아니지만, 사과할 줄 모르는 인간은 최악이다."}],"similar":[]},
  {"id":"d1725293495789","pattern":"〜とあって","core":"とあって","blankTarget":"とあって","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"特別な状況だからいつもとは違う現象が起きることを表すときに用います。 前件には特殊な状況、後件にはその状況下で起きる現象を述べます。 客観的かつ社会的な話題に対して用います。個人的な話題には使いにくいです。 既に発生したことにだけ使えます。","en":"because of the special situation; since it is...","ko":"…라는 특별한 상황이라; …이기 때문에"},"formation":{"ja":"動詞普通形＋とあって / イ形容詞普通形＋とあって / ナ形容詞普通形＋（だ）とあって / 名詞＋（だ）とあって","en":"動詞普通形＋とあって / イ形容詞普通形＋とあって / ナ形容詞普通形＋（だ）とあって / 名詞＋（だ）とあって","ko":"動詞普通形＋とあって / イ形容詞普通形＋とあって / ナ形容詞普通形＋（だ）とあって / 名詞＋（だ）とあって"},"examples":[{"ja":"ゴールデンウィークとあって高速道路は渋滞しているようだ。","en":"It's Golden Week, so the highways seem to be congested.","ko":"골든위크라서 고속도로가 정체된 모양이다."}],"similar":[]},
  {"id":"d1725293495790","pattern":"〜とあっては","core":"とあっては","blankTarget":"とあっては","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"仮定を表します。 前件には特別な状況が発生したこと、後件にはその特別な状況に対して行わなければならない行動、または自然に引き起こされる状態が述べられます。","en":"if it is the case that...; given that...","ko":"…라면; …인 이상"},"formation":{"ja":"動詞辞書形＋とあっては / 名詞＋とあっては","en":"動詞辞書形＋とあっては / 名詞＋とあっては","ko":"動詞辞書形＋とあっては / 名詞＋とあっては"},"examples":[{"ja":"彼女が応援してくれるとあっては絶対に負けられない。","en":"With her cheering me on, I absolutely cannot lose.","ko":"그녀가 응원해 준다면 절대 질 수 없다."}],"similar":[]},
  {"id":"d1725293495788","pattern":"〜とあれば","core":"とあれば","blankTarget":"とあれば","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前項の人物や物事のために全力で後件の実現にあたること、あるいは前項の状況下である以上必ず後件をしなければならないことを表します。 仮定の「なら」に言い換えられますが、「なら」には上記のようなニュアンスが含まれません。","en":"if it is for...; if it is the case that..., then necessarily","ko":"…라면; …을 위해서라면"},"formation":{"ja":"動詞普通形＋とあれば / い形容詞普通形＋とあれば / な形容詞語幹＋とあれば / 名詞＋とあれば","en":"動詞普通形＋とあれば / い形容詞普通形＋とあれば / な形容詞語幹＋とあれば / 名詞＋とあれば","ko":"動詞普通形＋とあれば / い形容詞普通形＋とあれば / な形容詞語幹＋とあれば / 名詞＋とあれば"},"examples":[{"ja":"彼女の頼みとあれば、協力しないわけにはいかない。","en":"If it's her request, I have no choice but to help.","ko":"그녀의 부탁이라면 협력하지 않을 수 없다."}],"similar":[]},
  {"id":"d1725293495794","pattern":"〜といい〜といい","core":"といい〜といい","blankTarget":"といい","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"例として２つ挙げ、それら全体について主観的な評価を述べる文型です。 挙げられた２つの例以外の存在も暗示します。 良い評価も悪い評価も可能です。","en":"whether in... or...; both... and...","ko":"…도 …도; …이든 …이든"},"formation":{"ja":"名詞＋といい＋名詞＋といい","en":"名詞＋といい＋名詞＋といい","ko":"名詞＋といい＋名詞＋といい"},"examples":[{"ja":"性能といい、デザインといい、この機種は素晴らしい。","en":"This model is excellent in both performance and design.","ko":"성능도 디자인도 이 기종은 훌륭하다."}],"similar":[]},
  {"id":"d1725293495798","pattern":"〜というか〜というか／といおうか〜といおうか","core":"というか〜というか","blankTarget":"というか","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"自分が感じている印象や判断を述べ、それを説明したり評価する文型です。 直接的に言うのを避けるようなときに使います。","en":"whether to call it... or...; or rather; I'm not sure if it's...","ko":"…라고 해야 할지 …라고 해야 할지; …이라기보다"},"formation":{"ja":"動詞普通形＋というか / い形普通形＋というか / な形容詞語幹＋というか / 名詞＋というか","en":"動詞普通形＋というか / い形普通形＋というか / な形容詞語幹＋というか / 名詞＋というか","ko":"動詞普通形＋というか / い形普通形＋というか / な形容詞語幹＋というか / 名詞＋というか"},"examples":[{"ja":"よく一緒に遊んでいた友人が転校してしまい、寂しいというか悲しいというか、この感情は誰にも説明できない。","en":"A friend I often played with transferred schools, and I don't know if it's loneliness or sadness—I can't explain this feeling to anyone.","ko":"자주 같이 놀던 친구가 전학을 가 버려서, 외롭다기보다 슬프다기보다, 이 감정은 누구에게도 설명할 수 없다."}],"similar":[]},
  {"id":"d1725293495796","pattern":"〜といったところだ／というところだ／ってところだ","core":"といったところだ","blankTarget":"といったところ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"数量を表す語に接続して、ある範囲内における境界線や目算を表します。 話者の主観的な判断、評価が前面に表れる文型です。","en":"at most; roughly; is about...","ko":"…정도다; 고작 …정도다"},"formation":{"ja":"数詞（＋助数詞）＋といったところだ／というところだ／ってところだ / 動詞辞書形＋といったところだ／というところだ／ってところだ","en":"数詞（＋助数詞）＋といったところだ／というところだ／ってところだ / 動詞辞書形＋といったところだ／というところだ／ってところだ","ko":"数詞（＋助数詞）＋といったところだ／というところだ／ってところだ / 動詞辞書形＋といったところだ／というところだ／ってところだ"},"examples":[{"ja":"明日の気温は１２度から２０度といったところです。","en":"Tomorrow's temperature should be around 12 to 20 degrees.","ko":"내일 기온은 12도에서 20도 정도 될 것이다."}],"similar":[]},
  {"id":"d1725293495795","pattern":"〜といったらありはしない／といったらありゃしない／ったらありゃしない／といったらない／ったらない","core":"といったらありはしない","blankTarget":"といったらありゃしない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"程度や状態を表す語について、それを強調する表現です。 「といったら」「ありはしない」の口語形はそれぞれ「ったら」「ありゃしない」です。 ～といったらありはしない ～といったらありゃしない ～ったらありゃしない ～といったらない ～ったらない","en":"extremely; incredibly; beyond words","ko":"이루 말할 수 없이 …하다; 더없이 …하다"},"formation":{"ja":"動詞辞書形＋といったらありゃしない / イ形辞書形＋といったらありゃしない / ナ形語幹（＋だ）＋といったらありゃしない / 名詞（＋だ）＋といったらありゃしない / い形辞書形＋こと＋といったらありゃしない","en":"動詞辞書形＋といったらありゃしない / イ形辞書形＋といったらありゃしない / ナ形語幹（＋だ）＋といったらありゃしない / 名詞（＋だ）＋といったらありゃしない / い形辞書形＋こと＋といったらありゃしない","ko":"動詞辞書形＋といったらありゃしない / イ形辞書形＋といったらありゃしない / ナ形語幹（＋だ）＋といったらありゃしない / 名詞（＋だ）＋といったらありゃしない / い形辞書形＋こと＋といったらありゃしない"},"examples":[{"ja":"泥遊びなんて汚いといったらありゃしない。","en":"Playing in the mud is unbelievably messy.","ko":"진흙 놀이는 더러워서 말도 못 한다."}],"similar":[]},
  {"id":"d1725293495799","pattern":"〜といわず〜といわず","core":"といわず〜といわず","blankTarget":"といわず","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"例として２つ挙げ、その２つを含む全体を表します。 後件には評価、状態、動作など幅広い内容がきます。 良くない内容を述べる場合のほうが多いです。","en":"whether at... or at...; not only... but...","ko":"…든 …든; …일 때든 …일 때든"},"formation":{"ja":"名詞＋といわず＋名詞＋といわず","en":"名詞＋といわず＋名詞＋といわず","ko":"名詞＋といわず＋名詞＋といわず"},"examples":[{"ja":"入浴中といわず、就寝中といわず、片時もスマホを手放さない。","en":"Whether I'm bathing or sleeping, I never let go of my phone for a moment.","ko":"목욕할 때든 잘 때든 한순간도 스마트폰을 손에서 놓지 않는다."}],"similar":[]},
  {"id":"d1725293495800","pattern":"〜ときたら／と来た日には","core":"ときたら","blankTarget":"ときたら","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"比較的身近な人物や物事を表す名詞に接続して、それらの極端な行為や性質に対する否定的な評価や強い非難を行う文型です。 接続される名詞は主語にあたります（話題提示）ので、「～ときたら」は「～は」に置き換えることができます。 「～きたら」の後の否定的な評価は省略されることがあります。 「～と来た日には」はやや硬い言い方です。","en":"as for...; speaking of... (with criticism)","ko":"…라니; …는 말이지(비난)"},"formation":{"ja":"名詞＋ときたら／と来た日には","en":"名詞＋ときたら／と来た日には","ko":"名詞＋ときたら／と来た日には"},"examples":[{"ja":"うちの猫ときたら、すぐトイレットペーパーで遊んで散らかしたがる。","en":"My cat—the moment it spots toilet paper, it wants to play with it and make a mess.","ko":"우리 집 고양이는 화장지만 보면 갖고 놀고 싶어 해서 어질러 놓는다."}],"similar":[]},
  {"id":"d1725293495801","pattern":"〜ところ／ところを","core":"ところ","blankTarget":"ところを","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"相手に対するお願いや謝罪、挨拶などをする前置きとして用います。 前件には前置き、後件には「申し訳ありません」「ありがとうございます」「お願いいたします」などの感謝、謝罪、依頼を述べます。 相手に何らかの迷惑をかける場合に用いるへりくだった表現です。 「そこのところ（そこんところ）」は前件を指す指示詞として用います。","en":"I'm sorry to trouble you while...; although you are...","ko":"…하시는 중에 죄송하지만; …한 상황인데"},"formation":{"ja":"名詞＋のところ（を） / イ形容詞基本形＋ところ（を）","en":"名詞＋のところ（を） / イ形容詞基本形＋ところ（を）","ko":"名詞＋のところ（を） / イ形容詞基本形＋ところ（を）"},"examples":[{"ja":"お忙しいところを申し訳ありませんが、よろしくお願いいたします。","en":"I'm sorry to bother you when you're busy, and I appreciate your cooperation.","ko":"바쁘신 중에 죄송합니다만, 잘 부탁드립니다."}],"similar":[]},
  {"id":"d1725293495807","pattern":"〜としたことが","core":"としたことが","blankTarget":"としたことが","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前項には人物を表す名詞が来て、後項ではその人が普段しないような失敗などの行動、そしてそれに対する驚きなどの感情を述べます。比較的身近な人物について述べることが多いです。 話者のその人物に対する評価はもともと高いからこそ、その人物がしてしまった意外な失敗に対する驚きのニュアンスを含みます。 既に発生したことにのみ使え、後ろにはよく「とは」や「なんて」と呼応します。更に「とは」「なんて」の後ろでは驚きなどの感想を述べますが、この部分は省略することができます。 慣用句として「私としたことが」という言い方があります。 いつもは失敗しない私が不注意から失敗してしまったことを意外だとして述べる言い方で、皮肉や謙遜にも使え、言い方によっては傲慢で偉そうな印象を与えることもあります。","en":"of all people, someone like... (doing something unexpected)","ko":"…인 사람이; …인 주제에"},"formation":{"ja":"名詞＋としたことが","en":"名詞＋としたことが","ko":"名詞＋としたことが"},"examples":[{"ja":"いつも成績の良い彼女としたことが、大学入試に落ちるとは驚きだ。","en":"It's surprising that she, who always gets good grades, failed the university entrance exam.","ko":"늘 성적이 좋은 그녀가 대학 입시에 떨어지다니 놀랍다."}],"similar":[]},
  {"id":"d1725293495809","pattern":"〜として〜ない","core":"として〜ない","blankTarget":"として","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「として」の前には１日、１人、１秒などの「１＋数詞」の形が接続され、少しも存在しないことを表します。数量が少ないことを強調する文型です。 「誰一人」「何ひとつ」「どれ一つ」は慣用表現で、それぞれ「誰」「何」「どれ」は省略可能です。 「彼みたいな人は２人としていない」のように、稀少を表すために２を使うこともできます。","en":"not a single...; not even one...","ko":"단 하나도 …하지 않다; 한 번도 …하지 않다"},"formation":{"ja":"名詞＋として～ない","en":"名詞＋として～ない","ko":"名詞＋として～ない"},"examples":[{"ja":"一瞬として気が抜けない。","en":"I can't let my guard down for even a moment.","ko":"한순간도 긴장을 늦출 수 없다."}],"similar":[]},
  {"id":"d1725293495808","pattern":"〜としてあるまじき／にあるまじき","core":"としてあるまじき","blankTarget":"としてあるまじき","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"職業や立場、人物を表す名詞に接続して、その地位に相応しくない程度や行為を批判・非難する文型です。 後件には言動や発言、行為、行動、態度などの語が接続されます。","en":"unbefitting of; unbecoming of; unacceptable for","ko":"…으로서 있을 수 없는; …답지 않은"},"formation":{"ja":"名詞＋としてあるまじき＋名詞 / 名詞＋にあるまじき＋名詞 / 名詞＋として許すまじき＋名詞","en":"名詞＋としてあるまじき＋名詞 / 名詞＋にあるまじき＋名詞 / 名詞＋として許すまじき＋名詞","ko":"名詞＋としてあるまじき＋名詞 / 名詞＋にあるまじき＋名詞 / 名詞＋として許すまじき＋名詞"},"examples":[{"ja":"あの反則はプロとしてあるまじき行為だ。","en":"That foul is behavior unbecoming of a professional.","ko":"저 반칙은 프로로서 있을 수 없는 행위다."}],"similar":[]},
  {"id":"d1725293495810","pattern":"〜とて","core":"とて","blankTarget":"とて","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"名詞について、それも例外ではなく他と同じであることを表します。","en":"even; too; as for... as well","ko":"…조차; …이라고 해서"},"formation":{"ja":"名詞＋とて","en":"名詞＋とて","ko":"名詞＋とて"},"examples":[{"ja":"今日も今日とてバイト。","en":"Today too, just like always, I have my part-time job.","ko":"오늘도 어김없이 아르바이트다."}],"similar":[]},
  {"id":"d1725293495791","pattern":"〜とばかりに／と言わんばかりに","core":"とばかりに","blankTarget":"とばかりに","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"発話文に接続して、そう言うくらいの程度で後項の動作が行われることを表します。 接続する発話文によっては、「今がチャンスだと思い～する」という意味に変わったりもします。その代表的な慣用表現に「ここぞとばかりに」があります。","en":"as if to say...; as though...","ko":"…라고 할 듯이; …라고 외치듯이"},"formation":{"ja":"発話文＋とばかりに / 発話文＋と言わんばかりに","en":"発話文＋とばかりに / 発話文＋と言わんばかりに","ko":"発話文＋とばかりに / 発話文＋と言わんばかりに"},"examples":[{"ja":"彼の登場で、待ってましたとばかりに大きな拍手が起こった。","en":"At his entrance, loud applause broke out as if everyone had been waiting for him.","ko":"그가 등장하자 기다렸다는 듯이 큰 박수가 터졌다."}],"similar":[]},
  {"id":"d1725293495792","pattern":"〜とは打って変わって／とは打って変わり／とはうってかわって／とはうってかわり","core":"とは打って変わって","blankTarget":"とはうってかわって","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"過去のある時点を表す名詞や過去の状態等に接続して、人や物事の状況・状態が完全に変化し、以前とは全く異なっていることを表します。","en":"in stark contrast to; completely different from","ko":"…와는 완전히 달라져; …와는 딴판으로"},"formation":{"ja":"名詞＋とは打って変わって / 名詞＋とは打って変わり","en":"名詞＋とは打って変わって / 名詞＋とは打って変わり","ko":"名詞＋とは打って変わって / 名詞＋とは打って変わり"},"examples":[{"ja":"昨日とはうってかわって今朝は寒い。","en":"In stark contrast to yesterday, this morning is cold.","ko":"어제와는 딴판으로 오늘 아침은 춥다."}],"similar":[]},
  {"id":"d1725293495802","pattern":"〜とまではいかないが／とまではいかないとしても／とまではいかないにしても","core":"とまではいかないが","blankTarget":"とまではいかないにしても","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前項の程度には達していない、あるいは達する必要はないが、少なくとも後項の程度に達している、達する必要があることを表します。 また、相手に対する要求にも使うことがあり、その場合は前項の程度までは求めないものの、少なくとも後項の程度は必要であることを表します。 この文法中の「いかない」はある程度に達していないことを表しています。 以下のように多くの言い方があります。 ～とまではいかないが ～とまではいかないにしても ～とまではいかないとしても ～とまではいかなくとも ～とはいかないまでも ～とはいかないにしても","en":"not quite to the extent of..., but at least...","ko":"…까지는 아니더라도; …정도까지는 안 되더라도"},"formation":{"ja":"動詞普通形＋とまではいかないが / イ形普通形＋とまではいかないが / ナ形語幹＋とまではいかないが / 名詞＋とまではいかないが","en":"動詞普通形＋とまではいかないが / イ形普通形＋とまではいかないが / ナ形語幹＋とまではいかないが / 名詞＋とまではいかないが","ko":"動詞普通形＋とまではいかないが / イ形普通形＋とまではいかないが / ナ形語幹＋とまではいかないが / 名詞＋とまではいかないが"},"examples":[{"ja":"Ａ国は貿易相手として重要とまではいかないにしても、利用する価値はある。","en":"Country A may not be important enough to count as a trading partner, but it is still worth using.","ko":"A국은 무역 상대로 중요하다고까지는 할 수 없어도 이용할 가치는 있다."}],"similar":[]},
  {"id":"d1725293495803","pattern":"〜とまでは言わないが／とまでは言わないとしても／とまでは言わないにしても","core":"とまでは言わないが","blankTarget":"とまでは言わないが","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前項の程度には達していない、あるいは達する必要はないが、少なくとも後項の程度に達している、達する必要があることを表します。 また、相手に対する要求にも使うことがあり、その場合は前項の程度までは求めないものの、少なくとも後項の程度は必要であることを表します。 以下のように多くの言い方があります。 ～とまでは言わないが ～とまでは言わないにしても ～とまでは言わないとしても ～とまでは言わなくとも ～とは言わないまでも ～とは言わないにしても","en":"I wouldn't go so far as to say..., but at least...","ko":"…까지는 아니라고 해도; …라고까지는 말하지 않겠지만"},"formation":{"ja":"動詞普通形＋とまでは言わないが / イ形普通形＋とまでは言わないが / ナ形語感＋とまでは言わないが / 名詞＋とまでは言わないが","en":"動詞普通形＋とまでは言わないが / イ形普通形＋とまでは言わないが / ナ形語感＋とまでは言わないが / 名詞＋とまでは言わないが","ko":"動詞普通形＋とまでは言わないが / イ形普通形＋とまでは言わないが / ナ形語感＋とまでは言わないが / 名詞＋とまでは言わないが"},"examples":[{"ja":"昔は良かったとまでは言わないが、ふと懐かしくなることもある。","en":"I wouldn't say the old days were better, but sometimes I feel nostalgic.","ko":"옛날이 좋았다고까지는 말하지 않겠지만, 문득 그리워질 때가 있다."}],"similar":[]},
  {"id":"d1725293495806","pattern":"〜ともなると／ともなれば","core":"ともなると","blankTarget":"ともなると","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"年齢や時間、状況を表す名詞や動詞に接続して、その時になったらどのようになるかという評価を後件で述べる文型です。","en":"once you reach...; when it comes to...","ko":"…쯤 되면; …에 이르면"},"formation":{"ja":"動詞辞書形＋ともなると／ともなれば / 名詞＋ともなると／ともなれば","en":"動詞辞書形＋ともなると／ともなれば / 名詞＋ともなると／ともなれば","ko":"動詞辞書形＋ともなると／ともなれば / 名詞＋ともなると／ともなれば"},"examples":[{"ja":"この年齢ともなると体が思うように動いてくれなくなる。","en":"At this age, my body no longer moves the way I want it to.","ko":"이 나이쯤 되면 몸이 마음대로 움직여 주지 않는다."}],"similar":[]},
  {"id":"d1747572696652","pattern":"〜とやら","core":"とやら","blankTarget":"とやら","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「とやら」は名詞に後接して、その名詞が表す事物についてあまり知らないことを表します。 例えば「キーマカレーとやらを食べてみた」と言えば、話し手は「キーマカレー」についてあまりよく知らないという意味が出てきます。あまりよく知らない状態が意図的に維持されているようであれば、話し手はその名詞が表す事物に対して意識的に距離をとり、馬鹿にしたり敬遠しているようなニュアンスも表れます（11）（12）。 「名詞＋とやら」はこれ全体で名詞として働くので、その後ろには「は」や「が」「を」などの格助詞がつけられます。","en":"something called...; so-called...","ko":"…라고 하는; 이른바 …라는"},"formation":{"ja":"名詞＋とやら","en":"名詞＋とやら","ko":"名詞＋とやら"},"examples":[{"ja":"３日間断食チャレンジとやらに挑戦しようと思っている。","en":"I'm thinking of trying out this so-called three-day fasting challenge.","ko":"3일 단식 챌린지라는 걸 한번 도전해 볼 생각이다."}],"similar":[]},
  {"id":"d1725293495793","pattern":"〜と言えなくもない","core":"と言えなくもない","blankTarget":"と言えなくもない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"二重否定による比較的消極的な肯定で主観的な評価を表します。 断定表現である「～といえる」には及ばない程度の表現です。","en":"one could say...; it is not wrong to say...","ko":"…라고 할 수 없지 않다; …라고도 할 수 있다"},"formation":{"ja":"動詞普通形＋と言えなくもない / い形容詞＋と言えなくもない / な形語幹（＋だ／である）＋と言えなくもない / 名詞（＋だ／である）＋と言えなくもない","en":"動詞普通形＋と言えなくもない / い形容詞＋と言えなくもない / な形語幹（＋だ／である）＋と言えなくもない / 名詞（＋だ／である）＋と言えなくもない","ko":"動詞普通形＋と言えなくもない / い形容詞＋と言えなくもない / な形語幹（＋だ／である）＋と言えなくもない / 名詞（＋だ／である）＋と言えなくもない"},"examples":[{"ja":"年収から見ると、彼はまあまあ成功してると言えなくもない。","en":"Judging by his annual income, you could say he's reasonably successful.","ko":"연봉으로 보면 그는 그럭저럭 성공했다고 할 수 없지 않다."}],"similar":[]},
  {"id":"d1725293495797","pattern":"〜と言っても／とは言っても／とは言え／と言えども／とは言うものの／とは言い条","core":"と言っても","blankTarget":"と言っても","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"逆接表現です。 前件で事実を認め、後件で前件から予想されるような結果にはならないことを述べます。 例文（２）（５）のように、「とは言っても」などと単独で接続詞的に用いることもできます。 最も口語で使われる表現は「～と言っても」「～とは言っても」で、最も硬い表現は「～とは言うものの」「～とは言い条」です。","en":"even if I say...; although; that said","ko":"…라고는 해도; …라고 하지만"},"formation":{"ja":"名詞＋（だ）と言っても / な形容詞語幹＋（だ）と言っても / 動詞普通形＋と言っても / い形容詞普通形＋と言っても","en":"名詞＋（だ）と言っても / な形容詞語幹＋（だ）と言っても / 動詞普通形＋と言っても / い形容詞普通形＋と言っても","ko":"名詞＋（だ）と言っても / な形容詞語幹＋（だ）と言っても / 動詞普通形＋と言っても / い形容詞普通形＋と言っても"},"examples":[{"ja":"いくら美味しいと言っても、見た目が良くなければ食べたくならない。","en":"No matter how delicious it is, if it doesn't look good, I don't want to eat it.","ko":"아무리 맛있다고 해도 보기에 좋지 않으면 먹고 싶지 않다."}],"similar":[]},
  {"id":"d1725293495787","pattern":"〜と相まって／が相まって／も相まって","core":"と相まって","blankTarget":"とが相まって","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"複数の物事の性質がお互いに作用し合うことを表します。 後件ではその相互作用によってもたらされる良い結果が述べられます。 一般に悪い内容が述べられることは少ないです（８）。","en":"combined with; together with; along with","ko":"…와 어우러져; …와 맞물려"},"formation":{"ja":"名詞＋と相まって / 名詞＋と＋名詞＋が相まって / 名詞＋と＋名詞＋とが相まって / 名詞＋も相まって","en":"名詞＋と相まって / 名詞＋と＋名詞＋が相まって / 名詞＋と＋名詞＋とが相まって / 名詞＋も相まって","ko":"名詞＋と相まって / 名詞＋と＋名詞＋が相まって / 名詞＋と＋名詞＋とが相まって / 名詞＋も相まって"},"examples":[{"ja":"綺麗な服と長い黒髪とが相まってお似合いです。","en":"The beautiful outfit combined with her long black hair looks lovely.","ko":"예쁜 옷과 긴 흑발이 어우러져 잘 어울린다."}],"similar":[]},
  {"id":"d1725293495697","pattern":"〜ないことには〜ない／てみないことには〜ない","core":"ないことには〜ない","blankTarget":"てみないことには","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"まず前件の動作を行わなければ、物事の実現が難しいことを表します。後件では「分からない」「できない」などの不可能を表す内容がきます。 「～てみないことには～ない」は、物事を試しに行ってみるような場面で用いることができます。 口語では「～ないと～ない」「～なければ～ない」の形でよく用いられます。","en":"unless you... you can't...; without doing..., it's impossible to...","ko":"…하지 않고서는 …할 수 없다"},"formation":{"ja":"動ない形＋ないことには～ない / 動て形＋みないことには～ない","en":"動ない形＋ないことには～ない / 動て形＋みないことには～ない","ko":"動ない形＋ないことには～ない / 動て形＋みないことには～ない"},"examples":[{"ja":"何事も経験してみないことには分からないだろう。","en":"You won't know unless you try things for yourself.","ko":"무엇이든 직접 경험해 보지 않고서는 모를 것이다."}],"similar":[]},
  {"id":"d1725293495696","pattern":"〜ないでもない／ないものでもない／なくもない","core":"ないでもない","blankTarget":"ないでもない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"消極的な断定を表します。 「～だ」と断定せずはっきり言いたくないような場合に使えます。 この文型のときは、思考や感情などに関係する語につきます。","en":"not that I don't...; I might just...; there is a slight possibility that...","ko":"…하지 않는 것도 아니다; …할 수도 있다"},"formation":{"ja":"動形＋ないでもない / 動形＋ないものでもない / 動形＋なくもない","en":"動形＋ないでもない / 動形＋ないものでもない / 動形＋なくもない","ko":"動形＋ないでもない / 動形＋ないものでもない / 動形＋なくもない"},"examples":[{"ja":"彼を見ていると、過去の自分を見ている気がしないでもない。","en":"Looking at him, I can't help feeling like I'm seeing my past self.","ko":"그를 보고 있으면 과거의 나를 보는 것 같은 기분이 들지 않는 것도 아니다."}],"similar":[]},
  {"id":"d1725293495700","pattern":"〜ないとも限らない","core":"ないとも限らない","blankTarget":"ないとも限らない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"ある物事の発生する可能性がわずかに残っていることを表す時に用いる文型です。話者の心配する気持ちが含まれ、前件か後件にはその可能性に対する何らかの対策を取るような内容が述べられることもあります。 多くの場合は、悪い事象が発生する可能性について述べます。 「いつ死ぬとも限らない（不知何时死）」等のように、「いつ」「どこ」などの疑問詞が来ると動詞辞書形でも接続可能な場合もあります。例（７）（８）。","en":"there's no guarantee that... won't happen; it might possibly...","ko":"…하지 않으리라고는 할 수 없다; …할지도 모른다"},"formation":{"ja":"動ない形＋ないとも限らない / イ形容詞語幹＋くないとも限らない / ナ形容詞語幹＋で／では／じゃ＋ないとも限らない / 名詞＋で／では／じゃ＋ないとも限らない","en":"動ない形＋ないとも限らない / イ形容詞語幹＋くないとも限らない / ナ形容詞語幹＋で／では／じゃ＋ないとも限らない / 名詞＋で／では／じゃ＋ないとも限らない","ko":"動ない形＋ないとも限らない / イ形容詞語幹＋くないとも限らない / ナ形容詞語幹＋で／では／じゃ＋ないとも限らない / 名詞＋で／では／じゃ＋ないとも限らない"},"examples":[{"ja":"災害で自分が被災しないとも限らないから食料等はちゃんと備蓄しておこうと思う。","en":"There's no guarantee I won't be affected by a disaster, so I want to keep food and supplies properly stocked.","ko":"재해로 내가 피해를 입지 않으리란 법도 없으니 식료품 등을 제대로 비축해 두려고 한다."}],"similar":[]},
  {"id":"d1725293495699","pattern":"〜ないものか／ないものだろうか","core":"ないものか","blankTarget":"ないものだろうか","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"ある物事が実現することを強く望む話者の気持ちを表します。 特にその物事の実現が困難である状況下で用いられやすい文法です。 独り言としても使えます。 口語形は「～ないもんか／ないもんだろうか」です。 同じく願望を表す文法に「【Ｎ３文法】～ないかな／てくれないかな／ないかしら／てくれないかしら（願望）」がありますが、こちらはそれほど事態が緊迫していない状況下でも用いることができる点で異なります。","en":"isn't there any way to...?; can't we...?","ko":"…할 수는 없을까; …할 방법이 없을까"},"formation":{"ja":"動ない形＋ないものか／ないものだろうか / 動ない形＋ないもんか／ないもんだろうか","en":"動ない形＋ないものか／ないものだろうか / 動ない形＋ないもんか／ないもんだろうか","ko":"動ない形＋ないものか／ないものだろうか / 動ない形＋ないもんか／ないもんだろうか"},"examples":[{"ja":"子どもに野菜を食べてもらう良い方法がないものだろうか。","en":"Isn't there a good way to get children to eat vegetables?","ko":"아이들이 채소를 먹게 할 좋은 방법이 없을까."}],"similar":[]},
  {"id":"d1725293495695","pattern":"〜ながらに／ながらの","core":"ながらに","blankTarget":"昔ながら","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"元々の状態から変わらないことを表します。 「生まれながら（天生）」「昔ながら（一如既往）」「いつもながら（和往常一样）」「涙ながら（流着泪的状态）」など、接続できる語は限られています。","en":"as it has always been; while in the state of...; ...as such","ko":"…인 채로; …그대로의"},"formation":{"ja":"名詞＋ながらに / 動ます形＋ながらに / 名詞＋ながらの＋名詞 / 動ます形＋ながらの＋名詞","en":"名詞＋ながらに / 動ます形＋ながらに / 名詞＋ながらの＋名詞 / 動ます形＋ながらの＋名詞","ko":"名詞＋ながらに / 動ます形＋ながらに / 名詞＋ながらの＋名詞 / 動ます形＋ながらの＋名詞"},"examples":[{"ja":"昔ながらの伝統を大切にしよう。","en":"Let's cherish the traditions that have been handed down since long ago.","ko":"옛날부터 이어져 온 전통을 소중히 하자."}],"similar":[]},
  {"id":"d1725293495704","pattern":"〜なら〜で","core":"なら〜で","blankTarget":"なら","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「その状況になるなら何らかの行動をするべきだ」という話者の判断を表す文型です。 後件にはアドバイス、命令、何らかの判断が来ます。不満が現れることが多いです。 一般的にはその行動をしたほうがよく、その責任があるような場面で用います。 「なら」の前後は同じ動詞を用います。","en":"if it is going to be..., then...; if you must, then do it properly","ko":"…라면 …대로; …할 거라면 …할 거면"},"formation":{"ja":"名詞＋なら＋名詞＋で / ナ形語幹＋なら＋ナ形語幹＋で / イ形普通形＋（の）なら＋イ形普通形＋で / 動詞普通形＋（の）なら＋動詞普通形＋で","en":"名詞＋なら＋名詞＋で / ナ形語幹＋なら＋ナ形語幹＋で / イ形普通形＋（の）なら＋イ形普通形＋で / 動詞普通形＋（の）なら＋動詞普通形＋で","ko":"名詞＋なら＋名詞＋で / ナ形語幹＋なら＋ナ形語幹＋で / イ形普通形＋（の）なら＋イ形普通形＋で / 動詞普通形＋（の）なら＋動詞普通形＋で"},"examples":[{"ja":"仕事辞めるなら辞めるでいいけど、次のこともちゃんと考えてるか？","en":"If you're going to quit your job, fine, but have you properly thought about what comes next?","ko":"일을 그만둘 거면 그만두더라도 좋지만, 다음 일은 제대로 생각하고 있는 거야?"}],"similar":[]},
  {"id":"d1725293495706","pattern":"〜ならいざしらず／はいざしらず","core":"ならいざしらず","blankTarget":"ならいざしらず","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"物事や行為に対する評価を行う文型です。 前件は許容できるが、後件は理解することも受け入れることもできないことを表します。 後件では、前件よりも程度がひどいことが述べられます。 話者の不平不満が強く表れます。","en":"I don't know about... but...; if it were..., that would be another matter","ko":"…라면 몰라도; …라면 별문제지만"},"formation":{"ja":"名詞＋ならいざしらず／はいざしらず / 動詞普通形＋ならいざしらず","en":"名詞＋ならいざしらず／はいざしらず / 動詞普通形＋ならいざしらず","ko":"名詞＋ならいざしらず／はいざしらず / 動詞普通形＋ならいざしらず"},"examples":[{"ja":"数千円のウイスキーならいざしらず、数万円台のを買うなら失敗したくない。","en":"For a whiskey costing a few thousand yen I might not care, but if I'm buying one in the tens of thousands, I don't want to fail.","ko":"몇천 엔짜리 위스키라면 몰라도, 몇만 엔대를 살 거라면 실패하고 싶지 않다."}],"similar":[]},
  {"id":"d1725293495705","pattern":"〜ならではだ／〜ならではの〜","core":"ならではだ","blankTarget":"ならでは","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"人物や組織、場所などの名詞に接続して、「それ特有の」「それが持っている特別な」という意味を表します。 「名詞＋ならではの＋名詞」で使う場合は、後件に必ず高評価を表す言葉が来ます。 低い評価をするときには原則使えません。","en":"unique to; only possible with; found only in","ko":"…만의 것이다; …이기에 가능한"},"formation":{"ja":"名詞＋ならではだ / 名詞＋ならではの＋名詞","en":"名詞＋ならではだ / 名詞＋ならではの＋名詞","ko":"名詞＋ならではだ / 名詞＋ならではの＋名詞"},"examples":[{"ja":"旅先ではその土地ならではの雰囲気を楽しみたい。","en":"When traveling, I want to enjoy the atmosphere that is unique to that place.","ko":"여행지에서는 그 땅에서만 느낄 수 있는 분위기를 즐기고 싶다."}],"similar":[]},
  {"id":"d1725293495707","pattern":"〜ならともかく／ならまだしも","core":"ならともかく","blankTarget":"ならともかく","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前件は許容できるけど後件は理解することも受け入れることもできないことを表します。 後件では、前件よりも程度が酷いことが述べられます。 話者の不平不満が強く表れる文型です。","en":"if it were..., that would be one thing, but...","ko":"…라면 몰라도; …라면 그렇다 쳐도"},"formation":{"ja":"名詞＋ならともかく／ならまだしも / な形容詞語幹＋ならともかく／ならまだしも / い形容詞普通形＋ならともかく／ならまだしも / 動詞普通形＋ならともかく／ならまだしも","en":"名詞＋ならともかく／ならまだしも / な形容詞語幹＋ならともかく／ならまだしも / い形容詞普通形＋ならともかく／ならまだしも / 動詞普通形＋ならともかく／ならまだしも","ko":"名詞＋ならともかく／ならまだしも / な形容詞語幹＋ならともかく／ならまだしも / い形容詞普通形＋ならともかく／ならまだしも / 動詞普通形＋ならともかく／ならまだしも"},"examples":[{"ja":"新入社員だから教えてくれるならともかく、全て自分で学べというのには無理がある。","en":"If I were a new employee and you were going to teach me, that would be one thing, but expecting me to learn everything on my own is unreasonable.","ko":"신입 사원이라서 가르쳐 준다면 몰라도, 모든 걸 혼자 배우라고 하는 건 무리다."}],"similar":[]},
  {"id":"d1725293495703","pattern":"〜なら別だ／なら話は別だ／となると別だ／となると話は別だ","core":"なら別だ","blankTarget":"なら別だ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"その条件下では例外であることを表します。 この文法を用いる場合はおよそ以下のような文型になり、普通は順当である内容（Ａ）と例外である内容（Ｂ）が対比して述べられます。 【 Ａ 】しかし、【 Ｂ 】なら話は別だ。 【 Ａ 】、【 Ｂ 】なら話は別だが。 【 Ｂ 】なら話は別だが、【 Ａ 】だ。","en":"if it is..., that is another matter; ...would be a different story","ko":"…라면 별문제다; …라면 이야기가 다르다"},"formation":{"ja":"名詞＋なら別だ／なら話は別だ／となると別だ／となると話は別だ / い形容詞普通形＋なら別だ／なら話は別だ／となると別だ／となると話は別だ / な形容詞語幹＋なら別だ／なら話は別だ／となると別だ／となると話は別だ / 動詞普通形＋なら別だ／なら話は別だ／となると別だ／となると話は別だ","en":"名詞＋なら別だ／なら話は別だ／となると別だ／となると話は別だ / い形容詞普通形＋なら別だ／なら話は別だ／となると別だ／となると話は別だ / な形容詞語幹＋なら別だ／なら話は別だ／となると別だ／となると話は別だ / 動詞普通形＋なら別だ／なら話は別だ／となると別だ／となると話は別だ","ko":"名詞＋なら別だ／なら話は別だ／となると別だ／となると話は別だ / い形容詞普通形＋なら別だ／なら話は別だ／となると別だ／となると話は別だ / な形容詞語幹＋なら別だ／なら話は別だ／となると別だ／となると話は別だ / 動詞普通形＋なら別だ／なら話は別だ／となると別だ／となると話は別だ"},"examples":[{"ja":"女性に言い寄られるのは困る。二次元なら別だが。","en":"I don't want women hitting on me. If it were a two-dimensional character, that would be another story.","ko":"여성에게 작업 걸리는 건 곤란하다. 2차원이라면 별문제지만."}],"similar":[]},
  {"id":"d1725293495735","pattern":"〜に〜ない","core":"に〜ない","blankTarget":"笑うに笑えなかった","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"したいけど何らかの理由でできないことを表します。心理的な理由の場合に使いやすいです。 話者の「本当はしたいけどできない」という気持ちを表すのが特徴です。 後件は動詞可能形の否定形が接続されます。 前件と後件の動詞は同じ動詞を用います。 「泣くに泣けない」は「泣きたくても泣けない」と同じ意味となります。 （物理的理由でできない） （心理的理由でできない）","en":"want to... but can't; unable to... even if one wants to","ko":"…하려야 …할 수 없다; …하고 싶어도 …할 수 없다"},"formation":{"ja":"動詞辞書形＋に＋動詞可能形の否定形＋ない","en":"動詞辞書形＋に＋動詞可能形の否定形＋ない","ko":"動詞辞書形＋に＋動詞可能形の否定形＋ない"},"examples":[{"ja":"彼の仕草がとても面白かったが、周囲は真剣に聞いているので私は笑うに笑えなかった。","en":"His gestures were very funny, but everyone around was listening seriously, so I couldn't bring myself to laugh.","ko":"그의 몸짓이 아주 우스웠지만 주변 사람들이 진지하게 듣고 있어서 나는 웃으려야 웃을 수 없었다."}],"similar":[]},
  {"id":"d1725293495749","pattern":"〜に〜を重ねて","core":"に〜を重ねて","blankTarget":"に","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"何度も繰り返した結果、難しいことを成し遂げたことを表します。 同じ名詞を２度繰り返して使います。","en":"after repeated...; through piling up...","ko":"…에 …을 거듭하여; 거듭된 … 끝에"},"formation":{"ja":"名詞Ａ＋に名詞Ａ＋を重ねて","en":"名詞Ａ＋に名詞Ａ＋を重ねて","ko":"名詞Ａ＋に名詞Ａ＋を重ねて"},"examples":[{"ja":"勉強に勉強を重ねて、難関大学に合格できた。","en":"Through repeated study, I was able to pass the entrance exam for a top university.","ko":"공부에 공부를 거듭한 끝에 명문 대학에 합격할 수 있었다."}],"similar":[]},
  {"id":"d1725293495714","pattern":"〜にあって／にあっては／あっても","core":"にあって","blankTarget":"にあっては","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"場所や状況、時間、立場などの名詞につき、「その状況下で」という意味を表します。 特別な状況、良くない状況などについて述べることが多い文型です。 書き言葉です。 「にあっても」は逆接表現です。","en":"in; under; at the time of; even in the situation of","ko":"…에 있어서; …라는 상황에서"},"formation":{"ja":"名詞＋にあって / 名詞＋にあっては / 名詞＋にあっても","en":"名詞＋にあって / 名詞＋にあっては / 名詞＋にあっても","ko":"名詞＋にあって / 名詞＋にあっては / 名詞＋にあっても"},"examples":[{"ja":"現代はイスに座るような仕事が増え運動能力の低下が懸念されているが、古代にあってはこうした運動能力は生活の中で十分に鍛えられ誰もが当たり前に肉体を使いこなしていた。","en":"In modern times, sedentary desk jobs have increased and there are concerns about declining physical ability, but in ancient times such ability was sufficiently trained in daily life, and everyone used their bodies as a matter of course.","ko":"현대에는 의자에 앉아 일하는 일이 늘어 신체 능력 저하가 우려되고 있지만, 고대에 있어서는 이런 신체 능력이 생활 속에서 충분히 단련되어 누구나 당연하게 몸을 활용하고 있었다."}],"similar":[]},
  {"id":"d1725293495731","pattern":"〜にかたくない(難くない)","core":"にかたくない(難くない)","blankTarget":"に難くない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"それほど難しくない、比較的容易などの意味を表します。 想像、想像する、察するなどのごく一部の単語にのみ接続されます。","en":"not hard to...; easy to...","ko":"…하기 어렵지 않다; …하는 것은 어렵지 않다"},"formation":{"ja":"動詞辞書形＋にかたくない / 名詞＋にかたくない","en":"動詞辞書形＋にかたくない / 名詞＋にかたくない","ko":"動詞辞書形＋にかたくない / 名詞＋にかたくない"},"examples":[{"ja":"それが事実だとすれば、遠からず良くない事が起こることは想像に難くない。","en":"If that is true, it is not hard to imagine that something bad will happen before long.","ko":"그것이 사실이라면 머지않아 좋지 않은 일이 일어날 것임은 상상하기 어렵지 않다."}],"similar":[]},
  {"id":"d1725293495729","pattern":"〜にかまけて","core":"にかまけて","blankTarget":"にかまけて","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"あることだけに気を取られて、それ以外の事がおろそかになっていることを表します。後項では本来しなければならないことができなかった等の悪い結果がきます。 「忙しさにかまけて」という言い方はよく用いられます。","en":"busy with... and neglecting...; preoccupied with","ko":"…에 정신이 팔려; …에 쫓겨"},"formation":{"ja":"名詞＋にかまけて","en":"名詞＋にかまけて","ko":"名詞＋にかまけて"},"examples":[{"ja":"本番は明日なのに、忙しさにかまけて練習できていなかった。","en":"The actual performance is tomorrow, but I was too caught up in being busy to practice.","ko":"본 무대는 내일인데 바쁘다는 것에 정신이 팔려 연습을 못 하고 있었다."}],"similar":[]},
  {"id":"d1725293495740","pattern":"〜にしたって／にしたところで","core":"にしたって","blankTarget":"にしたって","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"逆接表現です。 後件は良くない内容が述べられることが多いです。 この文型は数ある中から一つだけ取り挙げてそれについて述べます。その他の同種のものについても同様であることを表すのが特徴です。","en":"even...; even for...","ko":"…라고 해도; …조차도"},"formation":{"ja":"動詞普通形＋にしたって／にしたところで / い形容詞普通形＋にしたって／にしたところで / な形容詞語幹（＋である）＋にしたって／にしたところで / 名詞（＋である）＋にしたって／にしたところで","en":"動詞普通形＋にしたって／にしたところで / い形容詞普通形＋にしたって／にしたところで / な形容詞語幹（＋である）＋にしたって／にしたところで / 名詞（＋である）＋にしたって／にしたところで","ko":"動詞普通形＋にしたって／にしたところで / い形容詞普通形＋にしたって／にしたところで / な形容詞語幹（＋である）＋にしたって／にしたところで / 名詞（＋である）＋にしたって／にしたところで"},"examples":[{"ja":"一つの言葉にしたって、聞く側によって意味は変わる。","en":"Even a single word changes meaning depending on the listener.","ko":"한 단어조차 듣는 사람에 따라 의미가 달라진다."}],"similar":[]},
  {"id":"d1725293495741","pattern":"〜にして","core":"にして","blankTarget":"にして","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"ある段階に達したときを表します後件には物事の実現、成立、発見、理解などが述べられます。 主に時間や年齢、回数などを表す名詞に接続されます。 後件には「ようやく」「やっと」「初めて」などの語が呼応することがあります。","en":"only at the stage of...; not until...","ko":"…에 이르러서야; …번째에야"},"formation":{"ja":"時間、回数を表す名詞＋にして","en":"時間、回数を表す名詞＋にして","ko":"時間、回数を表す名詞＋にして"},"examples":[{"ja":"この難関試験に、３回目にしてようやく合格した。","en":"I finally passed this difficult exam on my third attempt.","ko":"이 어려운 시험에 세 번째에야 겨우 합격했다."}],"similar":[]},
  {"id":"d1725293495742","pattern":"〜にしてみたら／にしてみれば／にしてみても","core":"にしてみたら","blankTarget":"にしてみたら","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"人物を表す名詞について、人によって考え方や見方が異なることを述べる文型です。 この文型は一般的な概念に対して使いやすいです。 個人に対しては「～にとって」を使ったほうがもっと良いです。","en":"from the perspective of; as far as ... is concerned","ko":"…의 입장에서 보면; …로서는"},"formation":{"ja":"人物を表す名詞＋にしてみたら / 人物を表す名詞＋にしてみれば / 人物を表す名詞＋にしてみても","en":"人物を表す名詞＋にしてみたら / 人物を表す名詞＋にしてみれば / 人物を表す名詞＋にしてみても","ko":"人物を表す名詞＋にしてみたら / 人物を表す名詞＋にしてみれば / 人物を表す名詞＋にしてみても"},"examples":[{"ja":"花柄の服なんて男にしてみたら恥ずかしい。","en":"Floral clothes are embarrassing from a man's point of view.","ko":"꽃무늬 옷 같은 건 남자 입장에서는 부끄럽다."}],"similar":[]},
  {"id":"d1725293495745","pattern":"〜にたえる(堪える)","core":"にたえる(堪える)","blankTarget":"にたえる","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「見る」「読む」「鑑賞する」等のごく一部の語について、それをするだけの十分な価値があることを表します。 漢字は「堪える」です。","en":"worth doing (viewing, reading, etc.); deserving of","ko":"…할 가치가 있다; …에 견딜 만하다"},"formation":{"ja":"名詞＋にたえる / 動詞辞書形＋にたえる","en":"名詞＋にたえる / 動詞辞書形＋にたえる","ko":"名詞＋にたえる / 動詞辞書形＋にたえる"},"examples":[{"ja":"この映画は鑑賞するにたえる。","en":"This movie is worth watching.","ko":"이 영화는 감상할 가치가 있다."}],"similar":[]},
  {"id":"d1725293495748","pattern":"〜にとどまらず","core":"にとどまらず","blankTarget":"だけにとどまらず","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"時間や場所などの範囲を表す名詞に接続して、その範囲外にも影響が及んでいることを表します。 また、名詞以外に接続する場合は、例文（７）（８）のように、前項で述べたものに加え、更にそれ以上のことを後項で述べる累加・添加の用法もあります。 「～だけでなく」「～のみならず」「～ばかりでなく」に自由に言い換えることができます。","en":"not limited to; not only ... but also","ko":"…에 그치지 않고; …뿐만 아니라"},"formation":{"ja":"名詞＋（だけ／のみ）にとどまらず / 動詞普通形＋（だけ）にとどまらず / い形容詞＋だけにとどまらず / な形容詞語幹＋な／である＋だけにとどまらず","en":"名詞＋（だけ／のみ）にとどまらず / 動詞普通形＋（だけ）にとどまらず / い形容詞＋だけにとどまらず / な形容詞語幹＋な／である＋だけにとどまらず","ko":"名詞＋（だけ／のみ）にとどまらず / 動詞普通形＋（だけ）にとどまらず / い形容詞＋だけにとどまらず / な形容詞語幹＋な／である＋だけにとどまらず"},"examples":[{"ja":"彼女はアイドル活動だけにとどまらず、作家活動までしている。","en":"She does not stop at idol work; she has even taken up writing.","ko":"그녀는 아이돌 활동에 그치지 않고 작가 활동까지 하고 있다."}],"similar":[]},
  {"id":"d1725293495717","pattern":"〜には及ばない(およばない)","core":"には及ばない(およばない)","blankTarget":"に及ばない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"①「ＡはＢに（は）及ばない」の文型で、ＡよりもＢのほうが優れていることを表します。 このとき「～には敵わない（かなわない）」と同じ意味になります。 ②相手の気持ちや提案などに対して、「わざわざ～する必要ない」という婉曲的な拒否を表します。","en":"cannot compare with; be no match for; no need to","ko":"…에 미치지 못하다; …할 필요가 없다"},"formation":{"ja":"動詞辞書形＋に（は）及ばない / 名詞＋に（は）及ばない","en":"動詞辞書形＋に（は）及ばない / 名詞＋に（は）及ばない","ko":"動詞辞書形＋に（は）及ばない / 名詞＋に（は）及ばない"},"examples":[{"ja":"数学で言えば、私は彼に及ばない。","en":"When it comes to math, I am no match for him.","ko":"수학으로 말하자면 나는 그를 따라가지 못한다."}],"similar":[]},
  {"id":"d1725293495715","pattern":"〜には当たらない(あたらない)","core":"には当たらない(あたらない)","blankTarget":"にはあたらない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"相手の過剰な反応に対して「そこまで～する必要はない」と進言したり、諭すようなときに用いる文型です。特に感情を表す単語に接続されます。前項には「～からといって」「～だから／なので」などを伴って原因や理由が述べられることが多いです。","en":"there is no need to; not worth (worrying about)","ko":"…할 필요가 없다; …할 것까지는 없다"},"formation":{"ja":"動詞辞書形＋に（は）当たらない / 名詞＋に（は）当たらない","en":"動詞辞書形＋に（は）当たらない / 名詞＋に（は）当たらない","ko":"動詞辞書形＋に（は）当たらない / 名詞＋に（は）当たらない"},"examples":[{"ja":"多少ミスしたくらいでは心配にはあたらない。","en":"A minor mistake or two is nothing to worry about.","ko":"조금 실수한 정도로는 걱정할 필요가 없다."}],"similar":[]},
  {"id":"d1725293495716","pattern":"〜には無理がある","core":"には無理がある","blankTarget":"には無理がある","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"実現困難であることや現実性に欠けることを表します。","en":"be unrealistic; be unreasonable to (do)","ko":"…하기에는 무리가 있다"},"formation":{"ja":"動詞辞書形＋には無理がある / 名詞＋には無理がある","en":"動詞辞書形＋には無理がある / 名詞＋には無理がある","ko":"動詞辞書形＋には無理がある / 名詞＋には無理がある"},"examples":[{"ja":"これだけの量を一人で食べ尽くすには無理がある。","en":"It is unreasonable to expect one person to finish this much food.","ko":"이만한 양을 혼자 다 먹어치우기에는 무리가 있다."}],"similar":[]},
  {"id":"d1725293495733","pattern":"〜にもほどがある","core":"にもほどがある","blankTarget":"にもほどがある","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"相手の行為や程度が度を過ぎていたり、行き過ぎていることに対する戒めを表します。通常は良くない状況に使います。 この文型の「ほど」は、物事の節度やほどほどのところという意味です。 慣用表現に「冗談にもほどがある」があります。","en":"there is a limit to; ... goes too far","ko":"…에도 정도가 있다; 아무리 …해도 정도가 있다"},"formation":{"ja":"動詞辞書形＋にもほどがある / 動ない形＋にもほどがある / イ形容詞＋にもほどがある / イ形ない形＋にもほどがある / ナ形語幹＋にもほどがある","en":"動詞辞書形＋にもほどがある / 動ない形＋にもほどがある / イ形容詞＋にもほどがある / イ形ない形＋にもほどがある / ナ形語幹＋にもほどがある","ko":"動詞辞書形＋にもほどがある / 動ない形＋にもほどがある / イ形容詞＋にもほどがある / イ形ない形＋にもほどがある / ナ形語幹＋にもほどがある"},"examples":[{"ja":"誤字が多いにもほどがある。読めたもんじゃない。","en":"There is a limit to how many typos there can be. It is unreadable.","ko":"오자가 많아도 정도가 있다. 도저히 읽을 수가 없다."}],"similar":[]},
  {"id":"d1725293495734","pattern":"〜にも増して／にもまして","core":"にも増して","blankTarget":"にも増して","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"過去のある時点の状態と比較して、その時よりも程度が高くなることを後項で述べる比較の表現です。 前項には時間を表す言葉に接続されることが多いです。 良い事にも悪い事にも使うことができます。 慣用表現「以前にも増して」「いつにもまして」はよく使われます。","en":"more than ever; even more than","ko":"…보다도 더; …에 더하여"},"formation":{"ja":"名詞＋にも増して","en":"名詞＋にも増して","ko":"名詞＋にも増して"},"examples":[{"ja":"今日はいつにも増して寒いし早く帰りたい。","en":"Today is colder than usual, and I want to go home early.","ko":"오늘은 어느 때보다도 추워서 빨리 집에 가고 싶다."}],"similar":[]},
  {"id":"d1725293495750","pattern":"〜に依るところが大きい／によるところが大きい","core":"に依るところが大きい","blankTarget":"に依るところが大きい","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前項が後項に強く依存し、両者共に切り離せないような関係性であることを表します。 良いことにも悪いことにも使えます。","en":"depend largely on; owe much to","ko":"…에 의존하는 바가 크다; …에 힘입은 바가 크다"},"formation":{"ja":"名詞＋よるところが大きい","en":"名詞＋よるところが大きい","ko":"名詞＋よるところが大きい"},"examples":[{"ja":"「美しい」や「可愛い」などの美的感覚は個人の主観に依るところが大きい。","en":"Aesthetic judgments such as \"beautiful\" or \"cute\" depend largely on individual subjectivity.","ko":"'아름답다'나 '귀엽다' 같은 미적 감각은 개인의 주관에 의존하는 바가 크다."}],"similar":[]},
  {"id":"d1725293495732","pattern":"〜に越したことはない","core":"に越したことはない","blankTarget":"に越したことはない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"考えられる全ての方法の中でその方法が比較的良いことを表します。 社会通念上一般常識的なこと、当然なことに用います。 最も良いという積極的な評価ではなく、できればこの方法が良いという消極的評価を表す場合が多いです。","en":"nothing is better than; it is best to","ko":"…하는 게 가장 좋다; …에 미치는 것이 없다"},"formation":{"ja":"動詞辞書形＋に越したことはない / 動ない形＋に越したことはない / イ形辞書形＋に越したことはない / ナ形語幹＋に越したことはない / ナ形語幹＋である＋の＋に越したことはない","en":"動詞辞書形＋に越したことはない / 動ない形＋に越したことはない / イ形辞書形＋に越したことはない / ナ形語幹＋に越したことはない / ナ形語幹＋である＋の＋に越したことはない","ko":"動詞辞書形＋に越したことはない / 動ない形＋に越したことはない / イ形辞書形＋に越したことはない / ナ形語幹＋に越したことはない / ナ形語幹＋である＋の＋に越したことはない"},"examples":[{"ja":"健康のためには運動するに越したことはないが、習慣化するのが難しい。","en":"Nothing beats exercise for your health, but it is hard to make it a habit.","ko":"건강을 위해서는 운동하는 게 가장 좋지만, 습관으로 만드는 게 어렵다."}],"similar":[]},
  {"id":"d1725293495730","pattern":"〜に鑑みて／を鑑みて(かんがみて)","core":"に鑑みて","blankTarget":"に鑑み","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"状況、先例、規範などから考えて、何らかの対策や判断を下すことを表します。 物事を参照する意味を持つので、「～に鑑みて」と言うのが正しい表現ですが、現在では「～を鑑みて」の形でも用いられるようになってきています。","en":"in light of; in view of","ko":"…에 비추어; …을 감안하여"},"formation":{"ja":"名詞＋に鑑みて / 名詞＋を鑑みて","en":"名詞＋に鑑みて / 名詞＋を鑑みて","ko":"名詞＋に鑑みて / 名詞＋を鑑みて"},"examples":[{"ja":"昨今の状況に鑑み、今年度の事業計画を変更しました。","en":"In light of the current situation, we have changed this year's business plan.","ko":"최근의 상황을 감안하여 올해 사업 계획을 변경했습니다."}],"similar":[]},
  {"id":"d1725293495727","pattern":"〜に関わる(かかわる)","core":"に関わる(かかわる)","blankTarget":"に関わる","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"影響が及ぶ対象や範囲、関係する対象や範囲を表します。","en":"concern; involve; affect; be a matter of","ko":"…에 관련되다; …에 관계되다"},"formation":{"ja":"名詞＋関わる","en":"名詞＋関わる","ko":"名詞＋関わる"},"examples":[{"ja":"鬱は命に関わる重病である。","en":"Depression is a serious illness that can be life-threatening.","ko":"우울증은 생명에 관계되는 중병이다."}],"similar":[]},
  {"id":"d1725293495726","pattern":"〜に欠かせない／が欠かせない","core":"に欠かせない","blankTarget":"が欠かせない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"条件や量などが不足すると成立しない、つまり絶対になくてはならないことを表します。 「～にとってなくてはならない」「～になくてはならない」に言い換えることができます。","en":"indispensable to; essential for","ko":"…에 빼놓을 수 없다; …에 없어서는 안 된다"},"formation":{"ja":"名詞＋に欠かせない / 名詞＋が欠かせない","en":"名詞＋に欠かせない / 名詞＋が欠かせない","ko":"名詞＋に欠かせない / 名詞＋が欠かせない"},"examples":[{"ja":"この年になると晩酌が欠かせない。","en":"At my age, a drink with dinner is indispensable.","ko":"이 나이가 되면 저녁 술이 빠질 수 없다."}],"similar":[]},
  {"id":"d1725293495723","pattern":"〜に言わせれば／に言わせると","core":"に言わせれば","blankTarget":"に言わせれば","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"人物を表す名詞について、その人物の”自信に満ちた”意見を後項で述べる文法です。 偉そうに聞こえることもあるため、多用には注意が必要です。 「～にとって」と似ています。 「～から言わせれば」等と「から」を使うケースも見られます。","en":"if you ask ...; in ...'s view","ko":"…이 말하자면; …의 말에 따르면"},"formation":{"ja":"人物を表す名詞＋に言わせれば / 人物を表す名詞＋に言わせると","en":"人物を表す名詞＋に言わせれば / 人物を表す名詞＋に言わせると","ko":"人物を表す名詞＋に言わせれば / 人物を表す名詞＋に言わせると"},"examples":[{"ja":"私に言わせれば、タバコを止められないやつは意志が弱いだけだと思う。","en":"If you ask me, people who cannot quit smoking just have weak willpower.","ko":"내가 말하자면, 담배를 못 끊는 사람은 의지가 약할 뿐이라고 생각한다."}],"similar":[]},
  {"id":"d1725293495725","pattern":"〜に限らない／に限ったことではない／に限った問題ではない／〜に限らず〜も","core":"に限らない","blankTarget":"に限ったことではない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"述べられていることだけではなく、他にも同じ状況が存在することを表します。良くないことに対してのみ用いられます。 「～に限らない」をより強調した言い方が「～に限ったことではない」です。 「何も～に限らない／何も～に限ったことではない」のように、前に「何も」が呼応することもあります。 「～に限らず～も」は添加の文型です。","en":"not limited to; not only ... but also","ko":"…에 국한되지 않다; …만이 아니다"},"formation":{"ja":"名詞＋に限らない / 名詞＋に限ったことではない / 名詞＋に限った問題ではない / 名詞＋～に限らず＋～も","en":"名詞＋に限らない / 名詞＋に限ったことではない / 名詞＋に限った問題ではない / 名詞＋～に限らず＋～も","ko":"名詞＋に限らない / 名詞＋に限ったことではない / 名詞＋に限った問題ではない / 名詞＋～に限らず＋～も"},"examples":[{"ja":"少年犯罪が近年増加しているのは日本に限ったことではない。","en":"The recent rise in juvenile crime is not unique to Japan.","ko":"소년 범죄가 최근 증가하고 있는 것은 일본에 국한된 일이 아니다."}],"similar":[]},
  {"id":"d1725293495720","pattern":"〜に至って／に至り","core":"に至って","blankTarget":"に至って","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"ある特別な状況を表します。 「ようやく」「初めて」「やっと」「いまさら」等が呼応しやすいです。","en":"at the stage of; only when it comes to","ko":"…에 이르러서야; …단계에 이르러"},"formation":{"ja":"名詞＋に至って / 動詞辞書形＋に至って","en":"名詞＋に至って / 動詞辞書形＋に至って","ko":"名詞＋に至って / 動詞辞書形＋に至って"},"examples":[{"ja":"店を構えるに至って、ターゲットとなる客層を意識することはかなり大事だ。","en":"When it comes to opening a shop, being conscious of the target customers matters a great deal.","ko":"가게를 열게 되는 단계에 이르러서는 목표 고객층을 의식하는 것이 상당히 중요하다."}],"similar":[]},
  {"id":"d1725293495722","pattern":"〜に至っても","core":"に至っても","blankTarget":"に至っても","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"逆接を表します。 特別な事態に陥っても、状況や行動が変わらないことを述べる文型です。 「なお」「いまだに」「まだ」等が呼応しやすいです。 「事ここに至っても」は慣用表現です。 「今日に至っても」「現在に至っても」等の時は単なる逆接を表し、上記のような特別なニュアンスを持ちません。 例文（７）（８）。","en":"even when it comes to; even after reaching","ko":"…에 이르러서도; …한 상황에서도"},"formation":{"ja":"名詞＋に至っても / 動詞辞書形＋に至っても","en":"名詞＋に至っても / 動詞辞書形＋に至っても","ko":"名詞＋に至っても / 動詞辞書形＋に至っても"},"examples":[{"ja":"子どもには何でも挑戦させてあげたい。たとえそれで怪我をするに至っても、子どもにとって良い経験になり得るからだ。","en":"I want to let children try anything. Even if it leads to an injury, it can be a valuable experience for them.","ko":"아이들에게는 무엇이든 도전하게 해 주고 싶다. 설령 그로 인해 다치게 되더라도 아이에게 좋은 경험이 될 수 있기 때문이다."}],"similar":[]},
  {"id":"d1725293495719","pattern":"〜に至るまで","core":"に至るまで","blankTarget":"に至るまで","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"時間や場所などの語につき、その範囲の始点から終点の間にある全ての物事を表します。 前件に「～から」が呼応することがあります。 「～に至る」はある状態に達することを表します。これに終点を表す格助詞「まで」を組み合わせることで、ある状態に達するまでの過程、その範囲全てを指すようになっています。 「～に至るまで」と終点の「～まで」は似ています。 「～まで」は直線的な範囲にも円状の範囲にも使えます。 〇 ここからあそこまで歩いていきましょう。（直線的な範囲） 〇 東京まで飛行機で３時間かかります。（直線的な範囲） 〇 頭からつま先までずぶ濡れだ。（円状の範囲） 「～に至るまで」は円状の範囲には使えます。直線的な範囲には使いにくいです。","en":"all the way to; even; up to","ko":"…에 이르기까지; …까지도"},"formation":{"ja":"名詞＋に至るまで / 動詞辞書形＋に至るまで","en":"名詞＋に至るまで / 動詞辞書形＋に至るまで","ko":"名詞＋に至るまで / 動詞辞書形＋に至るまで"},"examples":[{"ja":"現在に至るまで、この事件の全容は解明されていない。","en":"To this day, the full picture of this case has not been clarified.","ko":"현재에 이르기까지 이 사건의 전모는 밝혀지지 않았다."}],"similar":[]},
  {"id":"d1725293495724","pattern":"〜に準じて／に準じ／に準じた","core":"に準じて","blankTarget":"に準じて","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"規格や根拠などの基準を表す名詞に接続し、その基準を用いて後件を処理することを表します。例文（１）～（４） また、他の物事を倣ったり、程度が同等であることを表す用法もあります。例文（５）～（８） 「準ずる（じゅんずる）」ということもあります。","en":"in accordance with; following (a standard)","ko":"…에 준하여; …을 기준으로"},"formation":{"ja":"名詞＋に準じて / 名詞＋に準じた＋名詞","en":"名詞＋に準じて / 名詞＋に準じた＋名詞","ko":"名詞＋に準じて / 名詞＋に準じた＋名詞"},"examples":[{"ja":"ISO規格に準じて運用する。","en":"We operate in accordance with ISO standards.","ko":"ISO 규격에 준하여 운영한다."}],"similar":[]},
  {"id":"d1725293495747","pattern":"〜に照らして／に照らし／に照らした","core":"に照らして","blankTarget":"に照らして","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"行為の根拠を表します。 主に憲法、法律、制度、規則、ルールなどの基準を表す名詞に接続します。 基準と行動を比べ、照らし合わせるようなニュアンスを持ちます。","en":"in light of; according to; against (a standard)","ko":"…에 비추어; …에 따라"},"formation":{"ja":"名詞＋に照らして / 名詞＋に照らした＋名詞","en":"名詞＋に照らして / 名詞＋に照らした＋名詞","ko":"名詞＋に照らして / 名詞＋に照らした＋名詞"},"examples":[{"ja":"犯罪は全て法に照らして裁かれる。","en":"All crimes are judged in accordance with the law.","ko":"범죄는 모두 법에 비추어 재판받는다."}],"similar":[]},
  {"id":"d1725293495736","pattern":"〜に則って／に則り／に則った","core":"に則って","blankTarget":"に則って","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"行為の根拠を表します。 主に憲法、法律、制度、規則、ルールなどの基準を表す名詞の他に、習慣、慣例、常識などの伝統的な概念を表す名詞に接続します。 お手本として従ったり参考にするというニュアンスを持ちます。","en":"in accordance with; following; based on","ko":"…에 따라; …을 좇아"},"formation":{"ja":"名詞＋に則って / 名詞＋に則った＋名詞","en":"名詞＋に則って / 名詞＋に則った＋名詞","ko":"名詞＋に則って / 名詞＋に則った＋名詞"},"examples":[{"ja":"一般常識に則って考えればすぐ分かることでしょう。","en":"Thinking according to common sense, it should be obvious.","ko":"일반 상식에 따라 생각하면 금방 알 수 있을 것이다."}],"similar":[]},
  {"id":"d1725293495743","pattern":"〜に即して／に即し／に即した","core":"に即して","blankTarget":"に即した","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"行動の根拠、行動の基準となるものを表します。 状況、事実、現実、経験、規則などの基準を表す名詞に接続します。 そのままそっくり手を加えずに参照するというニュアンスを持ちます。 語源は動詞「即する」です。","en":"in line with; grounded in; based on","ko":"…에 즉하여; …에 입각하여"},"formation":{"ja":"名詞＋に即して / 名詞＋に即した＋名詞","en":"名詞＋に即して / 名詞＋に即した＋名詞","ko":"名詞＋に即して / 名詞＋に即した＋名詞"},"examples":[{"ja":"現実に即した政策が実行されることを期待する。","en":"I hope policies grounded in reality will be implemented.","ko":"현실에 입각한 정책이 실행되기를 기대한다."}],"similar":[]},
  {"id":"d1725293495746","pattern":"〜に足る／に足りる／に足りない／に足らない","core":"に足る","blankTarget":"に足らない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「信頼する」「信じる」「信用する」「恐れる」「取る」等のごく一部の語について、それをするだけの十分な価値や必要性があることを表します。 「恐るるに足りない」「恐れるに足りない」「恐れるに足らない」「取るに足らない」などは慣用表現です。","en":"worthy of; sufficient to; not worth","ko":"…할 만하다; …에 값하다; …할 가치가 없다"},"formation":{"ja":"動詞辞書形＋に足る／足りる／足りない／足らない / 名詞＋に足る／足りる／足りない／足らない","en":"動詞辞書形＋に足る／足りる／足りない／足らない / 名詞＋に足る／足りる／足りない／足らない","ko":"動詞辞書形＋に足る／足りる／足りない／足らない / 名詞＋に足る／足りる／足りない／足らない"},"examples":[{"ja":"根拠が乏しく信頼するに足らない。","en":"The evidence is thin, so it is not worth trusting.","ko":"근거가 빈약하여 믿을 만하지 않다."}],"similar":[]},
  {"id":"d1725293495713","pattern":"〜に値する／に値しない","core":"に値する","blankTarget":"に値する","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"それをするだけの十分な価値があることを表します。","en":"be worth; deserve; not be worth","ko":"…할 가치가 있다; …에 값하다"},"formation":{"ja":"動詞辞書形＋に値する／に値しない / 名詞＋に値する／に値しない","en":"動詞辞書形＋に値する／に値しない / 名詞＋に値する／に値しない","ko":"動詞辞書形＋に値する／に値しない / 名詞＋に値する／に値しない"},"examples":[{"ja":"神への冒瀆は万死に値する。","en":"Blasphemy against God deserves death many times over.","ko":"신에 대한 모독은 만 번 죽어도 마땅하다."}],"similar":[]},
  {"id":"d1725293495738","pattern":"〜に如くはない(しくはない)／如くはなしだ","core":"に如くはない(しくはない)","blankTarget":"に如くはない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"それが最も良いことを表します。 「百聞は一見に如かず（百闻不如一见）」の「如かず」の原型が「如く（しく）」です。「如く（ごとく）」という読み方もありますが、この読み方をする時は比喩を表します。 この文法は、現代では使用頻度は低めで目にする機会は少ないです。","en":"there is nothing better than; it is best to","ko":"…만 한 것이 없다; …하는 것이 최선이다"},"formation":{"ja":"名詞＋に如くはない／如くはなしだ / 動詞辞書形＋に如くはない／如くはなしだ","en":"名詞＋に如くはない／如くはなしだ / 動詞辞書形＋に如くはない／如くはなしだ","ko":"名詞＋に如くはない／如くはなしだ / 動詞辞書形＋に如くはない／如くはなしだ"},"examples":[{"ja":"どこに危険が潜んでいるか分からない以上、用心するに如くはない。","en":"Since we do not know where danger lurks, the best course is to be cautious.","ko":"어디에 위험이 도사리고 있는지 알 수 없는 이상, 조심하는 것만 한 것이 없다."}],"similar":[]},
  {"id":"d1725293495739","pattern":"〜に忍びない","core":"に忍びない","blankTarget":"に忍びない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「忍ぶ」はもともと我慢する、堪えるという意味で、その否定形「忍びない」は我慢できない、堪えられないという意味になります。 接続できる動詞は少ないです。","en":"cannot bear to; cannot bring oneself to","ko":"…하기가 안타깝다; 차마 …할 수 없다"},"formation":{"ja":"動詞辞書形＋に忍びない","en":"動詞辞書形＋に忍びない","ko":"動詞辞書形＋に忍びない"},"examples":[{"ja":"大事なプレゼントなので捨てるに忍びない。","en":"It is an important gift, so I cannot bring myself to throw it away.","ko":"소중한 선물이라 차마 버릴 수가 없다."}],"similar":[]},
  {"id":"d1725293495737","pattern":"〜に負うところが大きい／に負うところが多い","core":"に負うところが大きい","blankTarget":"に負うところが大きい","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"人や物事から何かしらの恩恵を受けることを表します。 悪い内容にはほぼ使われず、良いことに対して用いることが多いです。 一般的には「～に負うところが大きい」を使いますが、稀に「～に負うところが多い」もあります。","en":"owe much to; be greatly indebted to","ko":"…에 힘입은 바가 크다"},"formation":{"ja":"名詞＋に負うところが大きい / （名詞＋に負うところが多い）","en":"名詞＋に負うところが大きい / （名詞＋に負うところが多い）","ko":"名詞＋に負うところが大きい / （名詞＋に負うところが多い）"},"examples":[{"ja":"今回の結果は彼の尽力に負うところが大きい。","en":"This result owes much to his efforts.","ko":"이번 결과는 그의 노력에 힘입은 바가 크다."}],"similar":[]},
  {"id":"d1725293495753","pattern":"〜のも無理はない","core":"のも無理はない","blankTarget":"のも無理はない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"ある物事の発生は必然的であることを表します。 多くの場合、前件に原因や理由を表す内容が来ます。 「無理はない／無理もない」の形で単独で使うこともできます。 ～のも無理はない ～のも無理もない ～のは無理もない ～のは無理はない","en":"it is no wonder that; it is only natural that","ko":"…하는 것도 무리가 아니다; …하는 것도 당연하다"},"formation":{"ja":"動詞辞書形＋のも無理はない / 動ない形＋のも無理はない","en":"動詞辞書形＋のも無理はない / 動ない形＋のも無理はない","ko":"動詞辞書形＋のも無理はない / 動ない形＋のも無理はない"},"examples":[{"ja":"大学受験はその後の人生を決めるくらい大きな出来事なので、不安に思うのも無理はない。","en":"It is no wonder they feel anxious, since the university entrance exam is a major event that can shape the rest of one's life.","ko":"대학 입시는 그 후의 인생을 좌우할 만큼 큰 사건이므로 불안해하는 것도 무리가 아니다."}],"similar":[]},
  {"id":"d1725293495754","pattern":"〜のをいいことに／ことをいいことに","core":"のをいいことに","blankTarget":"のをいいことに","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"趁着 利用 凭借 以…借口做某事","en":"taking advantage of; using ... as an excuse","ko":"…을 핑계로; …을 기회로 삼아"},"formation":{"ja":"動詞普通形＋のをいいことに / イ形普通形＋のをいいことに / ナ形語幹＋なのをいいことに / ナ形語幹＋であるのをいいことに / 名詞＋なのをいいことに","en":"動詞普通形＋のをいいことに / イ形普通形＋のをいいことに / ナ形語幹＋なのをいいことに / ナ形語幹＋であるのをいいことに / 名詞＋なのをいいことに","ko":"動詞普通形＋のをいいことに / イ形普通形＋のをいいことに / ナ形語幹＋なのをいいことに / ナ形語幹＋であるのをいいことに / 名詞＋なのをいいことに"},"examples":[{"ja":"研究室に私しかいないのをいいことに、音楽をスピーカーで流しながら仕事をする。","en":"Taking advantage of being the only one in the lab, I work with music playing through the speakers.","ko":"연구실에 나밖에 없는 것을 기회로 삼아 스피커로 음악을 틀어 놓고 일한다."}],"similar":[]},
  {"id":"d1725293495752","pattern":"〜の極み(きわみ)","core":"の極み(きわみ)","blankTarget":"の極み","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"極限の程度を表します。 痛恨の極み、疲労の極み、贅沢の極み、感激の極みなど、一部の語について強調する文型です。","en":"the height of; the extreme of","ko":"…의 극치; 더할 나위 없이 …함"},"formation":{"ja":"名詞＋の極みだ","en":"名詞＋の極みだ","ko":"名詞＋の極みだ"},"examples":[{"ja":"交通事故で多くの人が亡くなり、痛恨の極みだ。","en":"Many people died in the traffic accident; it is a matter of the deepest regret.","ko":"교통사고로 많은 사람이 죽어 통한의 극치다."}],"similar":[]},
  {"id":"d1725293495751","pattern":"〜の至り(いたり)","core":"の至り(いたり)","blankTarget":"の至り","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"光栄の至り、感激の至り、幸甚など、一部の語について感情を強調する文型です。 「若気の至り」は血気盛んな若者がする稚拙な行為、失敗を表す慣用表現です。","en":"the height of; utmost (emotion)","ko":"…의 지극함; 더할 나위 없음"},"formation":{"ja":"名詞＋の至りだ","en":"名詞＋の至りだ","ko":"名詞＋の至りだ"},"examples":[{"ja":"このような式典に参加でき、光栄の至りです。","en":"It is the greatest honor to be able to attend such a ceremony.","ko":"이러한 식전에 참여할 수 있어 더할 나위 없이 영광입니다."}],"similar":[]},
  {"id":"d1725293495648","pattern":"〜は〜てのことだ","core":"は〜てのことだ","blankTarget":"てのこと","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「ＡはＢてのことだ」という形を取り、Ａを実現するために必要な条件をＢで述べる文型です。ＢはＡの必要条件となるので、Ｂが無ければＡも成り立ちません。 この文型では後件であるＢを強調しています。","en":"it is only because; it is out of (consideration for)","ko":"…은 …해서인 것이다; …을 생각해서인 것이다"},"formation":{"ja":"動て形＋のこと / い形容詞て形＋のこと","en":"動て形＋のこと / い形容詞て形＋のこと","ko":"動て形＋のこと / い形容詞て形＋のこと"},"examples":[{"ja":"今回の決定は君を思ってのことだ。悪く思わないでくれ。","en":"This decision was made out of consideration for you. Please do not take it the wrong way.","ko":"이번 결정은 너를 생각해서 한 것이다. 나쁘게 생각하지 마."}],"similar":[]},
  {"id":"d1725293495646","pattern":"〜はさておき／はさておいて","core":"はさておき","blankTarget":"はさておき","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"取り上げる必要がないか、あるいは優先度が低い話題を後回しにし、最も重要な問題を提示するときに用いる文型です。 単に話題転換として「それはさておき」を使ったりもします。","en":"setting ... aside; leaving ... aside for now","ko":"…은 제쳐 두고; …은 논외로 하고"},"formation":{"ja":"名詞＋はさておき / 名詞＋はさておいて","en":"名詞＋はさておき / 名詞＋はさておいて","ko":"名詞＋はさておき / 名詞＋はさておいて"},"examples":[{"ja":"世間の評価はさておき、私は良かったと思う。","en":"Public opinion aside, I think it was good.","ko":"세간의 평가는 제쳐 두고, 나는 좋았다고 생각한다."}],"similar":[]},
  {"id":"d1725293495647","pattern":"〜はそっちのけで／をそっちのけで","core":"はそっちのけで","blankTarget":"そっちのけで","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"本来すべきことを放置して、別のことをすることを表します。 良いことにも悪いことにも使えます。","en":"neglecting; setting ... aside (to do something else)","ko":"…을 제쳐 두고; …은 뒷전으로 하고"},"formation":{"ja":"名詞＋（は）そっちのけで / 名詞＋（を）そっちのけで","en":"名詞＋（は）そっちのけで / 名詞＋（を）そっちのけで","ko":"名詞＋（は）そっちのけで / 名詞＋（を）そっちのけで"},"examples":[{"ja":"宿題そっちのけで遊んでばかりいる。","en":"I keep playing and completely neglect my homework.","ko":"숙제는 뒷전으로 하고 놀기만 한다."}],"similar":[]},
  {"id":"d1725293495627","pattern":"〜ぶる","core":"ぶる","blankTarget":"ぶって","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"本来そうではないのに、そのような素質や性質を持っていることを他人に見せつけるように振る舞うことを表します。その振る舞いに対する話者のマイナスの評価を表します。接続できる単語は限られています。 「可愛い子ぶる（かわいこぶる）」「もったいぶる（装模做样摆架子）」は慣用句です。","en":"pretend to be; act like; put on airs of","ko":"…인 척하다; …한 체하다"},"formation":{"ja":"名詞＋ぶる / な形容詞語幹＋ぶる / い形容詞語幹＋ぶる","en":"名詞＋ぶる / な形容詞語幹＋ぶる / い形容詞語幹＋ぶる","ko":"名詞＋ぶる / な形容詞語幹＋ぶる / い形容詞語幹＋ぶる"},"examples":[{"ja":"彼は被害者ぶっているが、真の被害者は私のほうだ。","en":"He acts like the victim, but I am the real victim here.","ko":"그는 피해자인 척하지만, 진짜 피해자는 나다."}],"similar":[]},
  {"id":"d1725293495622","pattern":"〜べからざる","core":"べからざる","blankTarget":"べからざる","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"不可能を表します。 「許すべからざる」「欠くべからざる」などの限られた言い方しかありません。","en":"must not; cannot; un- (in set phrases)","ko":"…해서는 안 될; …할 수 없는"},"formation":{"ja":"動詞辞書形＋べからざる＋名詞","en":"動詞辞書形＋べからざる＋名詞","ko":"動詞辞書形＋べからざる＋名詞"},"examples":[{"ja":"現代社会では、スマホは欠くべからざる存在となっている。","en":"In modern society, smartphones have become an indispensable presence.","ko":"현대 사회에서 스마트폰은 없어서는 안 될 존재가 되었다."}],"similar":[]},
  {"id":"d1725293495623","pattern":"〜べからず","core":"べからず","blankTarget":"べからず","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"禁止を表します。 主に看板や標識などの掲示に使われ、すべての人に対する禁止の呼びかけに使われます。 「する」は「するべからず」「すべからず」になる点に注意してください。","en":"must not; do not (prohibition on signs)","ko":"…해서는 안 된다; 금지"},"formation":{"ja":"動詞辞書形＋べからず","en":"動詞辞書形＋べからず","ko":"動詞辞書形＋べからず"},"examples":[{"ja":"ここにゴミを捨てるべからず。","en":"Do not dump garbage here.","ko":"여기에 쓰레기를 버려서는 안 된다."}],"similar":[]},
  {"id":"d1725293495625","pattern":"〜べくもない","core":"べくもない","blankTarget":"べくもない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"不可能を表す文型です。 実際はそうなることを望んでいるが、実際は状況的にできないというニュアンスを持ちます。比較的硬めの表現です。 「する」は「すべくもない」「するべくもない」になる点に注意。","en":"cannot possibly; there is no way to","ko":"…할 수 없다; …하기란 불가능하다"},"formation":{"ja":"動詞辞書形＋べくもない","en":"動詞辞書形＋べくもない","ko":"動詞辞書形＋べくもない"},"examples":[{"ja":"痩せたいけど、この体重では部分痩せなど望むべくもない。","en":"I want to lose weight, but at this weight, spot reduction is out of the question.","ko":"살을 빼고 싶지만 이 몸무게로는 부분 다이어트 같은 건 바랄 수도 없다."}],"similar":[]},
  {"id":"d1725293495687","pattern":"〜まくる","core":"まくる","blankTarget":"まくり","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"動作を何度も激しく繰り返す様子を表します。 「勝って勝って勝ちまくる」のように、「～て～て～まくる」で更に強調する言い方もあります。","en":"do ... over and over; do ... relentlessly","ko":"마구 …하다; …을 거듭하다"},"formation":{"ja":"動ます形＋まくる / 動て形＋動て形＋動ます形＋まくる","en":"動ます形＋まくる / 動て形＋動て形＋動ます形＋まくる","ko":"動ます形＋まくる / 動て形＋動て形＋動ます形＋まくる"},"examples":[{"ja":"７月に入ってから勝ちまくり、一気に首位に躍り出た。","en":"Since July began we have been winning one match after another and shot straight to the top.","ko":"7월에 들어서부터 계속 이겨서 단숨에 선두로 뛰어올랐다."}],"similar":[]},
  {"id":"d1725293495684","pattern":"〜までだ／までのことだ","core":"までだ","blankTarget":"までのことだ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"行為の目的や原因について説明し、その行為や目的がそれ以上でも以下でもないことを表します。 「ただ～しただけだ」と意味は同じです。 「～までのことだ」は「～までだ」の強調した言い方です。","en":"it is just that; that is all","ko":"…했을 뿐이다; …에 지나지 않는다"},"formation":{"ja":"動た形＋までだ / 動た形＋までのことだ","en":"動た形＋までだ / 動た形＋までのことだ","ko":"動た形＋までだ / 動た形＋までのことだ"},"examples":[{"ja":"私は事実を述べたまでのことだ。","en":"I merely stated the facts.","ko":"나는 사실을 말했을 뿐이다."}],"similar":[]},
  {"id":"d1725293495685","pattern":"〜までもない／までもなく","core":"までもない","blankTarget":"までもない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"当然のことだから、程度が低いから、重要度が低いからなどの理由で「わざわざ～する必要がない」ということを表します。","en":"there is no need to; need not","ko":"…할 필요까지는 없다"},"formation":{"ja":"動詞辞書形＋までもない / 動詞辞書形＋までもなく","en":"動詞辞書形＋までもない / 動詞辞書形＋までもなく","ko":"動詞辞書形＋までもない / 動詞辞書形＋までもなく"},"examples":[{"ja":"ここから家まであと少しなので、傘を差すまでもない。","en":"It is only a short walk home from here, so there is no need to put up an umbrella.","ko":"여기서 집까지 얼마 안 남았으니 우산을 쓸 필요까지는 없다."}],"similar":[]},
  {"id":"d1725293495688","pattern":"〜まみれ(塗れ)","core":"まみれ(塗れ)","blankTarget":"まみれ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"表面に汚い付着物がたくさんついていることを表します。 原則、ほこり、血、汗、泥、油、砂、ごみ、傷などの話者が汚い、不快と感じているものにだけ接続できます。 たまに例外もあります。例文（11）（12）（14） 「借金まみれ」は慣用的な表現です。 語源は一段動詞「塗れる（まみれる）」。 「汗まみれ」と「汗にまみれている」は同義です。","en":"covered in; smeared with; ... all over","ko":"…투성이; …가 잔뜩 묻은"},"formation":{"ja":"名詞＋まみれ","en":"名詞＋まみれ","ko":"名詞＋まみれ"},"examples":[{"ja":"タンスから昔の洋服を出したら、ほこりまみれだった。","en":"When I took the old clothes out of the chest, they were covered in dust.","ko":"옷장에서 옛날 옷을 꺼냈더니 먼지투성이였다."}],"similar":[]},
  {"id":"d1725293495689","pattern":"〜めく／めいて／めいた","core":"めく","blankTarget":"めいて","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「～のような感じがする」という意味の表現です。 「春めく」は「春のような感じがする」とほぼ同義なので完全に春であるときには使えません。例えば冬の終わりかけで暖かくなり春っぽさが表れてきたときなどなら大丈夫です。 春、謎、冗談、皮肉、説教などの特定の単語にのみ接続されます。","en":"have a touch of; feel like; smack of","ko":"…다운 느낌이 들다; …기운이 돌다"},"formation":{"ja":"名詞＋めく / 名詞＋めいて～ / 名詞＋めいた＋名詞","en":"名詞＋めく / 名詞＋めいて～ / 名詞＋めいた＋名詞","ko":"名詞＋めく / 名詞＋めいて～ / 名詞＋めいた＋名詞"},"examples":[{"ja":"季節はようやく春めいてきた。","en":"The season is finally starting to feel like spring.","ko":"계절이 드디어 봄기운이 돌기 시작했다."}],"similar":[]},
  {"id":"d1725293495692","pattern":"〜ものと思われる／ものと見られる","core":"ものと思われる","blankTarget":"ものと思われる","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"大多数の人が納得するような客観的な見方や推測を表します。","en":"it is thought that; it is believed that","ko":"…인 것으로 보인다; …라고 여겨진다"},"formation":{"ja":"動詞普通形＋ものと思われる／ものと見られる / い形容詞名詞修飾形＋ものと思われる／ものと見られる / な形容詞名詞修飾形＋ものと思われる／ものと見られる / 名詞＋ものと思われる／ものと見られる","en":"動詞普通形＋ものと思われる／ものと見られる / い形容詞名詞修飾形＋ものと思われる／ものと見られる / な形容詞名詞修飾形＋ものと思われる／ものと見られる / 名詞＋ものと思われる／ものと見られる","ko":"動詞普通形＋ものと思われる／ものと見られる / い形容詞名詞修飾形＋ものと思われる／ものと見られる / な形容詞名詞修飾形＋ものと思われる／ものと見られる / 名詞＋ものと思われる／ものと見られる"},"examples":[{"ja":"今朝庭にあった四角い箱は何者かが置いていったものと思われる。","en":"The square box in the yard this morning is thought to have been left there by someone.","ko":"오늘 아침 마당에 있던 네모난 상자는 누군가가 두고 간 것으로 보인다."}],"similar":[]},
  {"id":"d1725293495691","pattern":"〜も同然だ／も同然の／同然","core":"も同然だ","blankTarget":"同然に","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"実際は異なるものの、性質や状態から見るとほぼ同じであることを表します。 「～も同然だ」は文末で用い、「～も同然の」は後ろに名詞が接続されます。","en":"be as good as; be practically the same as","ko":"…이나 마찬가지다; …와 다름없다"},"formation":{"ja":"動た形（＋の）＋も同然だ／も同然の / 名詞＋（も）同然だ／（も）同然の","en":"動た形（＋の）＋も同然だ／も同然の / 名詞＋（も）同然だ／（も）同然の","ko":"動た形（＋の）＋も同然だ／も同然の / 名詞＋（も）同然だ／（も）同然の"},"examples":[{"ja":"実の娘同然に育ててくれた母に感謝している。","en":"I am grateful to my mother, who raised me as if I were her own daughter.","ko":"친딸이나 마찬가지로 키워 주신 어머니께 감사하고 있다."}],"similar":[]},
  {"id":"d1725293495833","pattern":"〜や否や／〜や","core":"や否や","blankTarget":"や否や","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前件の動作後すぐに後件の動作が発生することを表します。 既に発生したことに使います。 後件で予想外の出来事が述べられる場合、話者の驚きを表すことができます。","en":"as soon as; no sooner than; the moment","ko":"…하자마자; …는 순간"},"formation":{"ja":"動詞辞書形＋や / 動詞辞書形＋や否や","en":"動詞辞書形＋や / 動詞辞書形＋や否や","ko":"動詞辞書形＋や / 動詞辞書形＋や否や"},"examples":[{"ja":"お母さんの顔を見るや否や、安心したのか泣き出してしまった。","en":"The moment she saw her mother's face, she burst into tears, perhaps out of relief.","ko":"어머니의 얼굴을 보자마자 안심이 되었는지 울음을 터뜨리고 말았다."}],"similar":[]},
  {"id":"d1725293495836","pattern":"〜よう","core":"よう","blankTarget":"よう","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"悲しむ、起こる、驚く、喜ぶなどの感情を表す自動詞と、変わる、似るなどの状態を表す自動詞のます形に接続して、その方法や様子を表します。","en":"the way of ...; manner of ...; the extent of ...","ko":"…하는 모양; …하는 방식; …하는 정도"},"formation":{"ja":"動ます形＋よう","en":"動ます形＋よう","ko":"動ます形＋よう"},"examples":[{"ja":"その悲しみようは、見ている人さえも悲しくさせた。","en":"The depth of her grief made even onlookers feel sad.","ko":"그 슬픔의 정도는 보고 있던 사람들조차 슬프게 만들었다."}],"similar":[]},
  {"id":"d1725293495837","pattern":"〜ようが／ようと／ようとも／くても／くとも／かろうと／かろうが／〜ようが〜ようが／〜ようと〜ようと／〜ようが〜まいが／〜ようと〜まいと","core":"ようが","blankTarget":"おうと","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"仮定条件の逆接を表します。どのような状況であっても変わらないことを後件で述べます。 「たとえ」「どれだけ」「どんなに」「いくら」などの語が呼応することもあります。","en":"no matter ...; whether ... or ...; even if","ko":"…하든 …하든; …하더라도; …든지 …든지"},"formation":{"ja":"動意向形＋が／と／とも / 名詞＋だろうが／であろうが／だろうと／であろうと / な形容詞語幹＋だろうが／であろうが／だろうと／であろうと / い形容詞語幹＋くても／くとも／かろうと／かろうが / 動意向形＋が＋動まい形＋が","en":"動意向形＋が／と／とも / 名詞＋だろうが／であろうが／だろうと／であろうと / な形容詞語幹＋だろうが／であろうが／だろうと／であろうと / い形容詞語幹＋くても／くとも／かろうと／かろうが / 動意向形＋が＋動まい形＋が","ko":"動意向形＋が／と／とも / 名詞＋だろうが／であろうが／だろうと／であろうと / な形容詞語幹＋だろうが／であろうが／だろうと／であろうと / い形容詞語幹＋くても／くとも／かろうと／かろうが / 動意向形＋が＋動まい形＋が"},"examples":[{"ja":"たくさん本を買おうと、読まないなら無駄だ。","en":"No matter how many books you buy, it's a waste if you don't read them.","ko":"책을 많이 산다고 해도 읽지 않으면 소용없다."}],"similar":[]},
  {"id":"d1725293495839","pattern":"〜ようによっては／ようでは","core":"ようによっては","blankTarget":"ようによっては","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"方法や状況が異なると結果も変わってくることを述べる文型です。 もともと「～よう」は他動詞のます形に接続したときに方法を表し、「によって」は根拠を表します。この２つを組み合わせた言い方です。","en":"depending on how ...; according to how one ...","ko":"…하기에 따라서는; …하는 방식에 따라"},"formation":{"ja":"動ます形＋ようによって（は） / 動ます形＋ようで（は）","en":"動ます形＋ようによって（は） / 動ます形＋ようで（は）","ko":"動ます形＋ようによって（は） / 動ます形＋ようで（は）"},"examples":[{"ja":"この選手は癖が強いが、使いようによってはチームの中でうまく機能するはずだ。","en":"This player has strong quirks, but depending on how you use him, he should fit well into the team.","ko":"이 선수는 버릇이 강하지만 활용하기에 따라서는 팀 안에서 잘 기능할 것이다."}],"similar":[]},
  {"id":"d1725293495835","pattern":"〜よりない／よりほかにない／よりしかたがない","core":"よりない","blankTarget":"より仕方がない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"それをする以外に解決方法はないこと、たとえそうしたくなくてもそうする以外に方法がないことを表します。 多くの言い方がある点に注意が必要です。","en":"have no choice but to; there is no other way than","ko":"…할 수밖에 없다; …하는 수밖에 없다"},"formation":{"ja":"動詞辞書形＋よりない / 動詞辞書形＋よりほかない / 動詞辞書形＋よりほかにない / 動詞辞書形＋よりほかはない / 動詞辞書形＋よりしかたない","en":"動詞辞書形＋よりない / 動詞辞書形＋よりほかない / 動詞辞書形＋よりほかにない / 動詞辞書形＋よりほかはない / 動詞辞書形＋よりしかたない","ko":"動詞辞書形＋よりない / 動詞辞書形＋よりほかない / 動詞辞書形＋よりほかにない / 動詞辞書形＋よりほかはない / 動詞辞書形＋よりしかたない"},"examples":[{"ja":"自転車が壊れてしまった。歩いて行くより仕方がない。","en":"My bike broke, so I have no choice but to walk.","ko":"자전거가 고장 나 버렸다. 걸어갈 수밖에 없다."}],"similar":[]},
  {"id":"d1725293495814","pattern":"〜わ〜わ","core":"わ〜わ","blankTarget":"わ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"理由、原因を述べるときに使います。 何か２つの事象を挙げ、それらが理由で後件のような結果・状況になったことを表します。 話者の物事に対する煩わしさが表れやすいです。 良いことにも使えますが、どちらかというと悪い意味の用法が多めに感じます。","en":"what with ... and ...; both ... and ... (listing reasons)","ko":"…고 …고 해서; …에 …에 (이유를 나열)"},"formation":{"ja":"動詞辞書形＋わ＋動詞辞書形＋わ（で） / い形容詞基本形＋わ＋い形容詞基本形＋わ（で） / な形容詞語幹＋だわ＋な形容詞語幹＋だわ（で） / 名詞＋だわ＋名詞＋だわ（で）","en":"動詞辞書形＋わ＋動詞辞書形＋わ（で） / い形容詞基本形＋わ＋い形容詞基本形＋わ（で） / な形容詞語幹＋だわ＋な形容詞語幹＋だわ（で） / 名詞＋だわ＋名詞＋だわ（で）","ko":"動詞辞書形＋わ＋動詞辞書形＋わ（で） / い形容詞基本形＋わ＋い形容詞基本形＋わ（で） / な形容詞語幹＋だわ＋な形容詞語幹＋だわ（で） / 名詞＋だわ＋名詞＋だわ（で）"},"examples":[{"ja":"おごるとは言ったものの、みんな食うわ飲むわで５万円もかかった。","en":"I said I'd treat everyone, but what with all the eating and drinking, it cost 50,000 yen.","ko":"내가 쏘겠다고는 했지만 다들 먹고 마시고 해서 5만 엔이나 들었다."}],"similar":[]},
  {"id":"d1725293495826","pattern":"〜をおいて他にない","core":"をおいて他にない","blankTarget":"彼をおいて他に","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"限定を表す文型です。 人物や地域を表す名詞に接続し、「～だけだ」「～以外にない」という意味を表します。","en":"no one but; nothing but; none other than","ko":"…을 제외하고는 없다; …밖에 없다"},"formation":{"ja":"名詞＋をおいて他にない / 名詞＋をおいて他に～ない","en":"名詞＋をおいて他にない / 名詞＋をおいて他に～ない","ko":"名詞＋をおいて他にない / 名詞＋をおいて他に～ない"},"examples":[{"ja":"この仕事は彼をおいて他に任せられる人がいない。","en":"There is no one but him who can be entrusted with this job.","ko":"이 일은 그를 제외하고는 맡길 사람이 없다."}],"similar":[]},
  {"id":"d1725293495827","pattern":"〜をおろそかにする／〜をなおざりにする","core":"をおろそかにする","blankTarget":"が疎かになって","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"物事をいい加減に扱ったり、不真面目の処理することを表します。","en":"to neglect; to make light of; to be careless about","ko":"…을 소홀히 하다; …을 등한시하다"},"formation":{"ja":"名詞＋を疎かにする（をおろそかにする） / 名詞＋をなおざりにする","en":"名詞＋を疎かにする（をおろそかにする） / 名詞＋をなおざりにする","ko":"名詞＋を疎かにする（をおろそかにする） / 名詞＋をなおざりにする"},"examples":[{"ja":"ゲームばかりで私生活が疎かになっている。","en":"My personal life is being neglected because of all the gaming.","ko":"게임만 하느라 사생활이 소홀해지고 있다."}],"similar":[]},
  {"id":"d1725293495824","pattern":"〜をもって／をもちまして／をもってして／をもってすれば／をもってしても","core":"をもって","blankTarget":"をもって","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"時間を表す語に接続し、物事の開始あるいは終了を表します。 告知、通知、会議、式などの正式な場における挨拶などに用います。 「をもちまして」は「をもって」よりも硬い表現です。","en":"as of; with; by means of; at (a time)","ko":"…을 기해; …으로써; …을 가지고"},"formation":{"ja":"名詞＋をもって / 名詞＋をもちまして","en":"名詞＋をもって / 名詞＋をもちまして","ko":"名詞＋をもって / 名詞＋をもちまして"},"examples":[{"ja":"本日の営業は１９時をもって終了いたします。","en":"Today's business hours will end at 19:00.","ko":"오늘 영업은 19시를 기해 종료하겠습니다."}],"similar":[]},
  {"id":"d1725293495823","pattern":"〜をものともせずに","core":"をものともせずに","blankTarget":"をものともせずに","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"何らかの困難や障害を苦にせず乗り越えることを表す文型です。 前件には困難、後件ではそれを克服したことを述べます。 この文型の特徴は動作主の困難を恐れない勇敢さを表せる点にあります。そのため後件は常に良い内容がきます。","en":"undaunted by; without being deterred by","ko":"…에도 굴하지 않고; …을 아랑곳하지 않고"},"formation":{"ja":"名詞＋をものともせずに / 名詞＋をものともせず","en":"名詞＋をものともせずに / 名詞＋をものともせず","ko":"名詞＋をものともせずに / 名詞＋をものともせず"},"examples":[{"ja":"体の障害をものともせずに生き抜いた。","en":"He lived through life undaunted by his physical disability.","ko":"신체 장애에도 굴하지 않고 살아냈다."}],"similar":[]},
  {"id":"d1725293495828","pattern":"〜を押して／押し切って","core":"を押して","blankTarget":"を押して","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"何らかの困難を克服しようしていることを表す文型です。 この文型は「病気を押して」「反対を押し切って」等、接続できる語は非常に限られています。 「病気を押して」は、病気なのに無理して何かをするという意味です。","en":"despite; in spite of; overcoming","ko":"…을 무릅쓰고; …을 밀어붙여"},"formation":{"ja":"名詞＋を押して / 名詞＋を押し切って","en":"名詞＋を押して / 名詞＋を押し切って","ko":"名詞＋を押して / 名詞＋を押し切って"},"examples":[{"ja":"総理は病気を押して記者会見に現れた。","en":"The Prime Minister appeared at the press conference despite being ill.","ko":"총리는 병을 무릅쓰고 기자회견에 나타났다."}],"similar":[]},
  {"id":"d1725293495820","pattern":"〜を機に／を契機に","core":"を機に","blankTarget":"を機に","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"新しい事柄が始まるその起点を表します。前項にはその起点、後項にはその後の行為を述べます。「～をきっかけに」に言い換えることができますが、こちらは口語でよく用いられる表現です。一方、「～を機に／を契機に」はやや硬めな表現です。 前項と後項が同種の行為の時、この文型は使えません。前項と後項は全く異なる行為を述べ、前項が機会や動機となって後項とするという時に使えます。 ✕大阪への旅行を機に、京都にも旅行した。 ◯大阪への旅行を皮切りに、京都にも旅行した。 このような場合は「～を皮切りに」が使えます。","en":"taking ... as an opportunity; on the occasion of","ko":"…을 계기로; …을 기회로"},"formation":{"ja":"名詞＋を機に / 名詞＋を契機に / 動普通形＋のを機に / 動普通形＋のを契機に","en":"名詞＋を機に / 名詞＋を契機に / 動普通形＋のを機に / 動普通形＋のを契機に","ko":"名詞＋を機に / 名詞＋を契機に / 動普通形＋のを機に / 動普通形＋のを契機に"},"examples":[{"ja":"失恋を機に髪をばっさり切った。","en":"I cut my hair short after a breakup.","ko":"실연을 계기로 머리를 싹둑 잘랐다."}],"similar":[]},
  {"id":"d1725293495829","pattern":"〜を境に／を境にして","core":"を境に","blankTarget":"を境に","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"ある時点の前後でその性質は全く異なるものになることを表します。 主に時間を表す名詞に接続します。","en":"with ... as the boundary; from ... onward","ko":"…을 기점으로; …을 경계로"},"formation":{"ja":"名詞＋を境にして","en":"名詞＋を境にして","ko":"名詞＋を境にして"},"examples":[{"ja":"夏至を境に、日が短くなっていく。","en":"From the summer solstice onward, the days grow shorter.","ko":"하지를 기점으로 낮이 짧아져 간다."}],"similar":[]},
  {"id":"d1725293495821","pattern":"〜を禁じ得ない／禁じえない","core":"を禁じ得ない","blankTarget":"を禁じ得ない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"感情に関する名詞に接続して、その感情が心から湧いてきて抑えられない様子を表します。 驚き、怒り、恐怖、同情、疑問、違和感、涙、畏怖の念、焦燥、戦慄、笑い、興奮、悲しみ、戸惑いなど…","en":"cannot help but; cannot suppress one's ...","ko":"…을 금할 수 없다; …을 참을 수 없다"},"formation":{"ja":"名詞＋を禁じ得ない","en":"名詞＋を禁じ得ない","ko":"名詞＋を禁じ得ない"},"examples":[{"ja":"まさかの結果に驚きを禁じ得ない。","en":"I cannot help but be astonished at the unexpected result.","ko":"뜻밖의 결과에 놀라움을 금할 수 없다."}],"similar":[]},
  {"id":"d1725293495815","pattern":"〜を経て","core":"を経て","blankTarget":"を経て","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"場所（経由地）や時間、手段などの経由を表します。","en":"via; through; by way of","ko":"…을 거쳐; …을 경유하여"},"formation":{"ja":"名詞＋を経て","en":"名詞＋を経て","ko":"名詞＋を経て"},"examples":[{"ja":"韓国を経て日本に行く。","en":"I'll go to Japan via South Korea.","ko":"한국을 거쳐 일본에 간다."}],"similar":[]},
  {"id":"d1725293495817","pattern":"〜を顧みず／も顧みず","core":"を顧みず","blankTarget":"を顧みず","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"危険なことに立ち向かっていくこと、危険性を意に介さないことを表します。 後件は良い内容も悪い内容も可能です。","en":"without regard for; regardless of","ko":"…을 돌보지 않고; …을 아랑곳하지 않고"},"formation":{"ja":"名詞＋を顧みず / 名詞＋も顧みず","en":"名詞＋を顧みず / 名詞＋も顧みず","ko":"名詞＋を顧みず / 名詞＋も顧みず"},"examples":[{"ja":"危険を顧みず救助へ向かう。","en":"He rushes to the rescue without regard for danger.","ko":"위험을 돌보지 않고 구조하러 향한다."}],"similar":[]},
  {"id":"d1725293495816","pattern":"〜を控えて／〜を〜に控えて／〜が〜に控えて","core":"を控えて","blankTarget":"に","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"意味が２つあります。 ①「ＮをＮに控えて／ＮがＮに控えて」において、前項には物事、後項には時間を表す名詞が接続するときは、その物事が発生する前であることを表します。「Ｎを控えて」のように、後項は省略されることもあります。時間的な緊迫感と物事に対する緊張感を表せます。 物事が発生するまでの時間の長短に関わらず、話し手自身が切迫感が感じていれば、明日でも来週でも１か月後、１年後でも使うことができます。 ②「ＮをＮに控えて／ＮがＮに控えて」において、前項には人や物、後項には場所を表す名詞が接続するときは、それが位置的に近くにあることや、すぐ後ろにあることを表します。","en":"with ... coming up; on the eve of; situated just in front of","ko":"…을 앞두고; …을 바로 뒤에 두고"},"formation":{"ja":"名詞＋を控えて / 名詞＋を＋名詞＋に控えて / 名詞＋が＋名詞＋に控えて","en":"名詞＋を控えて / 名詞＋を＋名詞＋に控えて / 名詞＋が＋名詞＋に控えて","ko":"名詞＋を控えて / 名詞＋を＋名詞＋に控えて / 名詞＋が＋名詞＋に控えて"},"examples":[{"ja":"来週末に本番を控え、今日は夜通し練習だ。","en":"With the main event coming up next weekend, tonight is an all-night practice.","ko":"다음 주말에 본방을 앞두고 오늘은 밤새 연습이다."}],"similar":[]},
  {"id":"d1725293495822","pattern":"〜を前にして／〜を目前にして","core":"を前にして","blankTarget":"を前にして","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"意味は２つあります。 ①時間を表す名詞に接続して、その物事が発生する前であることを表します。時間的な緊迫感と物事に対する緊張感を表せます。物事が発生するまでの時間は非常に切迫していますので、発生までの時間が比較的長いものに使うことはできません。 ②人や物を表す名詞に接続して、目の前にあるものと対面していることを表します。 その物事に対する緊張感を表せます。","en":"facing; on the eve of; confronted with","ko":"…을 앞에 두고; …을 눈앞에 두고"},"formation":{"ja":"名詞＋を前にして / 名詞＋を目前にして","en":"名詞＋を前にして / 名詞＋を目前にして","ko":"名詞＋を前にして / 名詞＋を目前にして"},"examples":[{"ja":"明日の入試を前にして、今最も心配するのは会場までの交通状況だ。","en":"With tomorrow's entrance exam ahead, what worries me most right now is the traffic to the venue.","ko":"내일 입시를 앞두고 지금 가장 걱정되는 것은 회장까지의 교통 상황이다."}],"similar":[]},
  {"id":"d1725293495819","pattern":"〜を皮切りにして／を皮切りとして／を振り出しに","core":"を皮切りにして","blankTarget":"を皮切りに","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前項と同種の行為が次々行われていく様子を表します。前項にはその起点、後項にはその後の行為を述べます。「～を皮切りに」はよくニュースなどで使われます。一方「～を振り出しに」はあまり使われることはありませんが、どちらも同じ意味です。 前項と後項が同種の行為の時にだけこの文型使えます。 ✕転職を皮切りに、いろんなところに行ってみたい。 〇転職をきっかけに、いろんなところに行ってみたい。 このような場合は「～をきっかけに」「～を機に／を契機に」が使えます。","en":"starting with; beginning with","ko":"…을 시작으로; …을 필두로"},"formation":{"ja":"名詞＋を皮切りに（して） / 名詞＋を皮切りとして / 名詞＋を振り出しに / 動詞辞書形＋の＋を皮切りに（して） / 動詞辞書形＋の＋を皮切りとして","en":"名詞＋を皮切りに（して） / 名詞＋を皮切りとして / 名詞＋を振り出しに / 動詞辞書形＋の＋を皮切りに（して） / 動詞辞書形＋の＋を皮切りとして","ko":"名詞＋を皮切りに（して） / 名詞＋を皮切りとして / 名詞＋を振り出しに / 動詞辞書形＋の＋を皮切りに（して） / 動詞辞書形＋の＋を皮切りとして"},"examples":[{"ja":"東京を皮切りに全国７か所でコンサートが開かれる。","en":"Concerts will be held in seven cities nationwide, starting with Tokyo.","ko":"도쿄를 시작으로 전국 7곳에서 콘서트가 열린다."}],"similar":[]},
  {"id":"d1725293495825","pattern":"〜を蔑ろにする(〜をないがしろにする)","core":"を蔑ろにする(〜をないがしろにする)","blankTarget":"を蔑ろにすれ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"人や物事を軽視あるいは無いに等しいものとして扱うことを表します。","en":"to slight; to disregard; to make light of","ko":"…을 하찮게 여기다; …을 무시하다"},"formation":{"ja":"名詞＋を蔑ろにする（をないがしろにする）","en":"名詞＋を蔑ろにする（をないがしろにする）","ko":"名詞＋を蔑ろにする（をないがしろにする）"},"examples":[{"ja":"これを蔑ろにすれば後々必ず大事になる。","en":"If you make light of this, it will surely become a big deal later.","ko":"이것을 소홀히 하면 나중에 반드시 큰일이 난다."}],"similar":[]},
  {"id":"d1725293495831","pattern":"〜を余儀なくさせる","core":"を余儀なくさせる","blankTarget":"を余儀なくさせた","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"何らかの現象が人に対して行動を強制することを表します。 動作主体はその行為をすることを望んでおらず、嫌々行うようなニュアンスがあります。 多くの場合は悪い事態に対して使います。 主語は必ず原因です。 ニュースなどに用いられるような硬い表現です。主に書き言葉として使います。 「余儀ない」はもともと、他に方法がない状態、やむを得ない状態を表す形容詞です。 似ている文型に「【Ｎ１文法】～を余儀なくされる」がありますが、こちらの主語は原因ではなく人や集団です。","en":"to force (someone) to; to make ... unavoidable","ko":"…을 강요하다; …을 불가피하게 만들다"},"formation":{"ja":"名詞＋を余儀なくさせる","en":"名詞＋を余儀なくさせる","ko":"名詞＋を余儀なくさせる"},"examples":[{"ja":"両国関係の悪化が、プロジェクトの中止を余儀なくさせた。","en":"The deterioration of bilateral relations forced the project to be canceled.","ko":"양국 관계의 악화가 프로젝트 중단을 불가피하게 만들었다."}],"similar":[]},
  {"id":"d1725293495650","pattern":"〜以外の何ものでもない","core":"以外の何ものでもない","blankTarget":"以外の何ものでもない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前に接続した名詞を強調し、それ以外ではなくまさしくそれであるという意味を表します。 「～は～以外の何ものでもない」という文型でよく使います。","en":"nothing but; nothing other than","ko":"… 그 자체다; …외에 아무것도 아니다"},"formation":{"ja":"名詞＋以外の何ものでもない","en":"名詞＋以外の何ものでもない","ko":"名詞＋以外の何ものでもない"},"examples":[{"ja":"タバコを吸うのは害以外の何ものでもない。","en":"Smoking is nothing but harmful.","ko":"담배를 피우는 것은 해악 그 자체다."}],"similar":[]},
  {"id":"d1725293495659","pattern":"〜以前","core":"以前","blankTarget":"以前","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"取り上げるべき問題はそれではなく、それよりも前段階の問題であることを表す文型です。 批判するときに用います。","en":"not even a question of; before even considering; beside the point","ko":"… 이전의 문제다; …은 논하기 전의 문제다"},"formation":{"ja":"名詞＋以前 / 名詞＋である以前 / ～かどうか以前 / 肯定形＋否定形＋以前","en":"名詞＋以前 / 名詞＋である以前 / ～かどうか以前 / 肯定形＋否定形＋以前","ko":"名詞＋以前 / 名詞＋である以前 / ～かどうか以前 / 肯定形＋否定形＋以前"},"examples":[{"ja":"仕事をサボるというのは、仕事ができるできない以前の問題だ。","en":"Slacking off at work is not even a question of ability.","ko":"일을 빼먹는다는 것은 일을 잘하느냐 못하느냐 이전의 문제다."}],"similar":[]},
  {"id":"d1725293495645","pattern":"〜羽目になる／羽目に陥る","core":"羽目になる","blankTarget":"羽目になった","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"あることが原因でたちまち困難に陥ってしまうことを表す文法です。","en":"to end up having to; to be forced into (a bad situation)","ko":"…하는 신세가 되다; …할 수밖에 없게 되다"},"formation":{"ja":"動詞辞書形＋羽目になる","en":"動詞辞書形＋羽目になる","ko":"動詞辞書形＋羽目になる"},"examples":[{"ja":"原因不明のエラーが発生して再インストールする羽目になった。","en":"An unknown error occurred and I ended up having to reinstall.","ko":"원인 불명의 오류가 발생해서 재설치하는 신세가 되었다."}],"similar":[]},
  {"id":"d1725293495668","pattern":"〜気取り(きどり)","core":"気取り(きどり)","blankTarget":"気取り","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"本来そうではないのに、そのような素質や性質を持っていることを他人に見せつけるように振る舞うことを表します。 例文（１）のように中立的な評価にも使えますが、マイナスの評価に使う場合が比較的多いです。 動詞「気取る」の連用形で、接尾辞的に用います。 似ている文法に「【Ｎ１文法】～ぶる」がありますが、こちらはマイナスの評価だけを表します。","en":"posing as; putting on the airs of","ko":"…인 척하는; …행세를 하는"},"formation":{"ja":"名詞＋気取り","en":"名詞＋気取り","ko":"名詞＋気取り"},"examples":[{"ja":"女優気取りで歩くと女性らしさがより際立つ。","en":"Walking as if she were an actress makes her femininity stand out even more.","ko":"여배우인 척 걸으면 여성스러움이 더욱 돋보인다."}],"similar":[]},
  {"id":"d1725293495672","pattern":"〜極まる／〜極まりない","core":"極まる","blankTarget":"極まりない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"極限の程度を表します。 「極まる」「極まりない」は形式上肯否の対立が見られますが、この言い方の時はその対立が解消され、いずれも同じ意味となります。どちらかというと「極まりない」のほうが使用頻度が高めです。 書き言葉として用います。 「感極まる」は非常に感動することを表す慣用表現です。","en":"extremely; utterly; to the utmost","ko":"더할 나위 없이; 극도로"},"formation":{"ja":"ナ形語幹＋（なこと）＋極まりない／極まる / ナ形語幹＋（であること）＋極まりない／極まる / イ形容詞＋こと＋極まりない／極まる","en":"ナ形語幹＋（なこと）＋極まりない／極まる / ナ形語幹＋（であること）＋極まりない／極まる / イ形容詞＋こと＋極まりない／極まる","ko":"ナ形語幹＋（なこと）＋極まりない／極まる / ナ形語幹＋（であること）＋極まりない／極まる / イ形容詞＋こと＋極まりない／極まる"},"examples":[{"ja":"一日何時間もゲームをするのは不健全なこと極まりない。","en":"Playing games for hours on end every day is utterly unhealthy.","ko":"하루에 몇 시간씩 게임을 하는 것은 더할 나위 없이 불건전하다."}],"similar":[]},
  {"id":"d1725293495669","pattern":"〜嫌いがある／きらいがある","core":"嫌いがある","blankTarget":"きらいがある","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"良くない傾向や性質があることを表します。 ここでいう「嫌い」とは、良くない傾向のことです。 ほとんどの場合、人の性格や内面的な特徴について述べるときに使います。 似ている文型「【Ｎ３文法】～がち」はその回数が多いことに使えますが、「～きらいがある」は使えません。","en":"have a tendency to; be inclined to (negatively)","ko":"…하는 경향이 있다; …하기 쉽다"},"formation":{"ja":"名詞＋の＋きらいがある / 動詞辞書形＋きらいがある / 動ない形＋きらいがある","en":"名詞＋の＋きらいがある / 動詞辞書形＋きらいがある / 動ない形＋きらいがある","ko":"名詞＋の＋きらいがある / 動詞辞書形＋きらいがある / 動ない形＋きらいがある"},"examples":[{"ja":"彼は物事を独断で考えるきらいがある。","en":"He has a tendency to think about things dogmatically.","ko":"그는 일을 독단적으로 생각하는 경향이 있다."}],"similar":[]},
  {"id":"d1725293495656","pattern":"〜言わずもがな","core":"言わずもがな","blankTarget":"言わずもがな","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"【言わずもがな＋の＋名詞】 「言わなくてもいい」「言うべきではない」「言わないほうがいい」と同じ。 後ろによく「こと」が接続され、「言わずもがなだ」で終わることもできる。 【名詞＋は言わずもがな】 「～は言うまでもなく～も」「～はもとより～も」「～はもちろん～も」と同じ。 前項にはわざわざ言わなくても明らかになっていることが述べられる。","en":"needless to say; better left unsaid","ko":"말할 것도 없다; 말하지 않는 편이 낫다"},"formation":{"ja":"言わずもがな＋の／な＋名詞 / 名詞＋は言わずもがな","en":"言わずもがな＋の／な＋名詞 / 名詞＋は言わずもがな","ko":"言わずもがな＋の／な＋名詞 / 名詞＋は言わずもがな"},"examples":[{"ja":"この作品、ストーリーがいいのは言わずもがな。","en":"In this work, it goes without saying that the story is good.","ko":"이 작품은 스토리가 좋다는 것은 말할 것도 없다."}],"similar":[]},
  {"id":"d1725293495661","pattern":"〜限りだ","core":"限りだ","blankTarget":"限り","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"感情を表す語に接続する場合は、その程度を強調します。","en":"extremely; nothing but (an emotion)","ko":"…을 따름이다; …하기 그지없다"},"formation":{"ja":"感情を表すイ形容詞＋限りだ / 感情を表すナ形容詞＋な＋限りだ / 感情を表す名詞＋の＋限りだ","en":"感情を表すイ形容詞＋限りだ / 感情を表すナ形容詞＋な＋限りだ / 感情を表す名詞＋の＋限りだ","ko":"感情を表すイ形容詞＋限りだ / 感情を表すナ形容詞＋な＋限りだ / 感情を表す名詞＋の＋限りだ"},"examples":[{"ja":"彼、宝くじが当たるなんて羨ましい限りだ。","en":"How enviable that he won the lottery — I'm jealous beyond words.","ko":"그가 복권에 당첨되다니 부러울 따름이다."}],"similar":[]},
  {"id":"d1725293495840","pattern":"〜故に／が故／故だ","core":"故に","blankTarget":"故だ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"原因や理由を表します。 「～故に」には動詞や形容詞、副詞が後続します。 「～故の」には名詞が後続します。 また、「故に」自体は接続詞として単独で使用できます。意味は「だから」と同義。 古語由来の表現なので硬い表現です。","en":"because of; due to; therefore","ko":"…때문에; …인 까닭에"},"formation":{"ja":"名詞／ナ形容詞語幹＋故に / 名詞／ナ形容詞語幹＋である故に / 名詞／ナ形容詞語幹＋が故に / 名詞／ナ形容詞語幹＋であるが故に / イ形普通形＋故に","en":"名詞／ナ形容詞語幹＋故に / 名詞／ナ形容詞語幹＋である故に / 名詞／ナ形容詞語幹＋が故に / 名詞／ナ形容詞語幹＋であるが故に / イ形普通形＋故に","ko":"名詞／ナ形容詞語幹＋故に / 名詞／ナ形容詞語幹＋である故に / 名詞／ナ形容詞語幹＋が故に / 名詞／ナ形容詞語幹＋であるが故に / イ形普通形＋故に"},"examples":[{"ja":"自分がモテないのは自分の容姿の悪さ故だ。","en":"The reason I'm not popular is my poor looks.","ko":"내가 인기가 없는 것은 내 외모가 나쁜 탓이다."}],"similar":[]},
  {"id":"d1725293495757","pattern":"〜始末だ","core":"始末だ","blankTarget":"始末だ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"良くないことが続き、結局良くない結果になったことを表します。 話者の残念な気持ちが含まれます。 「あげく～始末だ」「挙句の果てに～始末だ」という文型になることがあります。","en":"to end up (in a bad state); to come to a sorry pass","ko":"…꼴이 되다; …지경에 이르다"},"formation":{"ja":"動詞辞書形＋始末だ / 動ない形＋始末だ / この＋始末だ / その＋始末だ / あの＋始末だ","en":"動詞辞書形＋始末だ / 動ない形＋始末だ / この＋始末だ / その＋始末だ / あの＋始末だ","ko":"動詞辞書形＋始末だ / 動ない形＋始末だ / この＋始末だ / その＋始末だ / あの＋始末だ"},"examples":[{"ja":"昨晩飲み過ぎたせいでこの始末だ。","en":"I drank too much last night, and now look at the state I'm in.","ko":"어젯밤 과음한 탓에 이 꼴이다."}],"similar":[]},
  {"id":"d1725293495761","pattern":"〜術がない","core":"術がない","blankTarget":"術がない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「術（すべ）」とは、方法を表します。「術がない」はつまり方法がないということです。動詞辞書形に接続せずとも、「術がない」という形単独で使うこともできます。（３） なお、「成す術がない」は慣用句です。","en":"there is no way to; have no means to","ko":"…할 방법이 없다; …할 도리가 없다"},"formation":{"ja":"動詞辞書形＋術がない","en":"動詞辞書形＋術がない","ko":"動詞辞書形＋術がない"},"examples":[{"ja":"言いたいことはたくさんあるが、それを上手く伝える術がない。","en":"I have a lot I want to say, but no way to convey it well.","ko":"하고 싶은 말은 많지만 그것을 잘 전달할 방법이 없다."}],"similar":[]},
  {"id":"d1725293495811","pattern":"〜尽くす(つくす)","core":"尽くす(つくす)","blankTarget":"尽くせ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"動ます形に接続して、動作の完了、残らず全てやり切ることを表します。特に物事の数量的な部分に着目し、たくさんあるものを残らず最後まで終わらせたという点について述べるときに用います。 似ている文型に「～切る」がありますが、こちらは動作の完遂を強調したい場合に用います。 また、「全力を尽くす」「手段を尽くす」「彼に尽くす」のように、単独で用いることもできます。","en":"to do ... thoroughly; to exhaust; to the fullest","ko":"…을 다 하다; …을 철저히 하다"},"formation":{"ja":"動ます形＋尽くす / 動ます形＋尽くせないほどだ / 動ます形＋尽くせないほどの＋名詞","en":"動ます形＋尽くす / 動ます形＋尽くせないほどだ / 動ます形＋尽くせないほどの＋名詞","ko":"動ます形＋尽くす / 動ます形＋尽くせないほどだ / 動ます形＋尽くせないほどの＋名詞"},"examples":[{"ja":"この夏は語り尽くせないほどの思い出を作りたい。","en":"This summer I want to make so many memories that I can't even describe them all.","ko":"이번 여름에는 다 말할 수 없을 만큼 많은 추억을 만들고 싶다."}],"similar":[]},
  {"id":"d1725293495670","pattern":"〜切りがない(きりがない)","core":"切りがない(きりがない)","blankTarget":"たらきりがない","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"その動作をひとたびすれば、それ以降際限なく行い続けてしまう、行い続けられることを表します。 例文（７）（８）のように、単に「きりがない」や、動て形に接続して「～てもきりがない」とされるときは、限度がないことを表します。","en":"endless; no end to","ko":"끝이 없다; 한이 없다"},"formation":{"ja":"動詞辞書形＋と＋きりがない / 動仮定形＋ば＋きりがない / 動た形＋らきりがない","en":"動詞辞書形＋と＋きりがない / 動仮定形＋ば＋きりがない / 動た形＋らきりがない","ko":"動詞辞書形＋と＋きりがない / 動仮定形＋ば＋きりがない / 動た形＋らきりがない"},"examples":[{"ja":"彼の悪いところを挙げたらきりがない。","en":"Once you start listing his faults, there's no end to it.","ko":"그의 나쁜 점을 들자면 끝이 없다."}],"similar":[]},
  {"id":"d1725293495760","pattern":"〜損なう／損ねる／損じる","core":"損なう","blankTarget":"損ねた","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"動ます形に接続して、してみたけど何らかの理由で失敗した、実際はできるのに不注意か何かでできなかったという意味を表します。 「損なう」「損ねる」「損じる」いずれも意味は同じです。","en":"to fail to; to miss (doing)","ko":"…하지 못하다; …을 놓치다"},"formation":{"ja":"動ます形＋損なう（そこなう） / 動ます形＋損ねる（そこねる） / 動ます形＋損じる（そんじる）","en":"動ます形＋損なう（そこなう） / 動ます形＋損ねる（そこねる） / 動ます形＋損じる（そんじる）","ko":"動ます形＋損なう（そこなう） / 動ます形＋損ねる（そこねる） / 動ます形＋損じる（そんじる）"},"examples":[{"ja":"逃げた飼い猫を捕まえ損ねた。","en":"I failed to catch my runaway cat.","ko":"도망친 반려묘를 잡지 못했다."}],"similar":[]},
  {"id":"d1725293495644","pattern":"〜如き／如く／如し(ごとき／ごとく／ごとし)","core":"如き","blankTarget":"ごとく","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"像…一样 如… 就好像…","en":"like; as if; as","ko":"…처럼; …과 같이"},"formation":{"ja":"動詞辞書形＋が＋如き＋名詞 / 動詞辞書形＋が＋如く（連用） / 動詞辞書形＋が＋如し（文末） / 動詞辞書形＋かの＋如き＋名詞 / 動詞辞書形＋かの＋如く（連用）","en":"動詞辞書形＋が＋如き＋名詞 / 動詞辞書形＋が＋如く（連用） / 動詞辞書形＋が＋如し（文末） / 動詞辞書形＋かの＋如き＋名詞 / 動詞辞書形＋かの＋如く（連用）","ko":"動詞辞書形＋が＋如き＋名詞 / 動詞辞書形＋が＋如く（連用） / 動詞辞書形＋が＋如し（文末） / 動詞辞書形＋かの＋如き＋名詞 / 動詞辞書形＋かの＋如く（連用）"},"examples":[{"ja":"汗が滝のごとく流れ出す。","en":"Sweat pours out like a waterfall.","ko":"땀이 폭포처럼 흘러나온다."}],"similar":[]},
  {"id":"d1725293495755","pattern":"〜抜きに〜ない／抜きで〜ない／抜きにしては〜ない","core":"抜きに〜ない","blankTarget":"抜きでは","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"あるものが無ければ不可能であることを表します。 後項は「～ない」「～できない」「～れない」などの否定形、可能否定形、または否定的な内容が呼応します。","en":"cannot ... without; impossible without","ko":"…이 없이는 …할 수 없다"},"formation":{"ja":"名詞＋（を）抜きに～ない / 名詞＋（を）抜きで～ない / 名詞＋（を）抜きにしては～ない","en":"名詞＋（を）抜きに～ない / 名詞＋（を）抜きで～ない / 名詞＋（を）抜きにしては～ない","ko":"名詞＋（を）抜きに～ない / 名詞＋（を）抜きで～ない / 名詞＋（を）抜きにしては～ない"},"examples":[{"ja":"Ａ社の歴史を語るなら、創業者の伝説抜きでは語れない。","en":"If you're going to tell the history of Company A, you can't do it without the legend of its founder.","ko":"A사의 역사를 말하자면 창업자의 전설 없이는 말할 수 없다."}],"similar":[]},
  {"id":"d1725293495649","pattern":"〜放題(ほうだい)","core":"放題(ほうだい)","blankTarget":"放題","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"動ます形に接続して、思う存分したいだけするという意味を表します。 「好き放題」という言い方もあります。 似ている文法に「【Ｎ０文法】～三昧（ざんまい）」があります。こちらは名詞にのみ接続して似たような意味を表します。","en":"all you can (eat/drink); as much as one likes; free rein","ko":"무한리필; 마음껏; 제멋대로"},"formation":{"ja":"動ます形＋放題 / 動ます形＋たい放題","en":"動ます形＋放題 / 動ます形＋たい放題","ko":"動ます形＋放題 / 動ます形＋たい放題"},"examples":[{"ja":"焼肉食べ放題大人一人３０００円","en":"All-you-can-eat yakiniku, 3,000 yen per adult.","ko":"고기 무한리필 성인 1인 3,000엔."}],"similar":[]},
  {"id":"d1725293495657","pattern":"いざ〜となると","core":"いざ〜となると","blankTarget":"いざ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"考えてるだけでは別に何とも思わないのに、実際にその行動をすることになったときにやっとその難しさに気付くことを表します。","en":"when it comes to actually doing ...; when the time comes to ...","ko":"막상 …하려고 하면; 실제로 …할 때가 되면"},"formation":{"ja":"いざ＋動辞書形＋となると / いざ＋名詞＋となると","en":"いざ＋動辞書形＋となると / いざ＋名詞＋となると","ko":"いざ＋動辞書形＋となると / いざ＋名詞＋となると"},"examples":[{"ja":"いざ話したり書くとなると簡単な言葉しか使えなくなっちゃう。","en":"When it comes to actually speaking or writing, I end up able to use only simple words.","ko":"막상 말하거나 쓰려고 하면 쉬운 말밖에 쓰지 못하게 된다."}],"similar":[]},
  {"id":"d1725293495658","pattern":"いざとなると〜／いざとなれば〜／いざとなったら〜","core":"いざとなると〜","blankTarget":"いざとなったら","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"「いざ」とはこれから何か始めようとする時や重要な時のことです。 「万が一の時は」「その時になったら」という意味を表します。 後項では物事が進展する様子を述べ、話者の対象に対する驚きや意外性を表します。 単独で使うため接続はありません。","en":"when it comes down to it; in an emergency","ko":"막상 일이 닥치면; 비상시에는"},"formation":{"ja":"※単独で使用します。","en":"※単独で使用します。","ko":"※単独で使用します。"},"examples":[{"ja":"傘はいざとなったら武器にもなる。","en":"An umbrella can even become a weapon when the time comes.","ko":"우산은 막상 필요할 때는 무기도 된다."}],"similar":[]},
  {"id":"d1725293495660","pattern":"いずれにしても〜／いずれにしろ〜／いずれにせよ〜／どっちみち〜","core":"いずれにしても〜","blankTarget":"どっちみち","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"前件で様々な可能性や選択肢があることに触れ、そのどちらを選んだとしても結果や取るべき行動は変わらず、後件が話の重点であることを表します。 「いずれ」は「どれ」という意味です。 「どっちみち」は話し言葉で、「いずれにしても」は話し言葉、書き言葉でも用いることができます。 「いずれにしろ」「いずれにせよ」は主に書き言葉で用いられます。","en":"in any case; either way; anyway","ko":"어차피; 어느 쪽이든; 아무튼"},"formation":{"ja":"いずれにしても＋文 / いずれにしろ＋文 / いずれにせよ＋文 / どっちみち＋文","en":"いずれにしても＋文 / いずれにしろ＋文 / いずれにせよ＋文 / どっちみち＋文","ko":"いずれにしても＋文 / いずれにしろ＋文 / いずれにせよ＋文 / どっちみち＋文"},"examples":[{"ja":"今会社を出ても、どっちみち終電には間に合わない。","en":"Even if I leave the office now, I won't make the last train anyway.","ko":"지금 회사를 나서도 어차피 막차는 못 탈 것이다."}],"similar":[]},
  {"id":"d1725293495673","pattern":"ここ〜というもの／この〜というもの","core":"ここ〜というもの","blankTarget":"ここ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"その期間で何らかの大きな変化が生じたことを表す文型です。","en":"for the past ...; over these ...","ko":"지난 … 동안; 이 … 동안"},"formation":{"ja":"ここ＋時間を表す名詞＋というもの / この＋時間を表す名詞＋というもの","en":"ここ＋時間を表す名詞＋というもの / この＋時間を表す名詞＋というもの","ko":"ここ＋時間を表す名詞＋というもの / この＋時間を表す名詞＋というもの"},"examples":[{"ja":"ここ３年というもの、毎日必死に仕事に打ち込んできた。","en":"For the past three years, I've thrown myself into my work every day.","ko":"지난 3년 동안 매일 필사적으로 일에 매달려 왔다."}],"similar":[]},
  {"id":"d1725293495674","pattern":"これといって〜ない／これといった〜ない／これという〜ない","core":"これといって〜ない","blankTarget":"これといって","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"語るほどのものではないことを表します。後項には「も」や「～ない」が伴います。 「これといって」の後には動詞や形容詞が、「これといった／これという」の後には名詞が接続されます。","en":"nothing in particular; no particular ...","ko":"특별히 …한 것은 없다; 딱히 …한 것은 없다"},"formation":{"ja":"これといって＋動詞＋～ない / これといって＋形容詞＋～ない / これといった＋名詞＋～ない / これという＋名詞＋～ない","en":"これといって＋動詞＋～ない / これといって＋形容詞＋～ない / これといった＋名詞＋～ない / これという＋名詞＋～ない","ko":"これといって＋動詞＋～ない / これといって＋形容詞＋～ない / これといった＋名詞＋～ない / これという＋名詞＋～ない"},"examples":[{"ja":"私には、これといって自慢できることがない。","en":"I don't have anything in particular to be proud of.","ko":"나는 특별히 자랑할 만한 것이 없다."}],"similar":[]},
  {"id":"d1725293495763","pattern":"ただ〜あるのみ／ただ〜のみ","core":"ただ〜あるのみ","blankTarget":"ただ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"限定の文法です。すべきことは一つしかないことを表します。 「～するしかない」に言い換えることができますが、「～しかない」は話者の悲観的なニュアンスが含まれるのに対し、「～あるのみだ」は話者の積極的な強い意志を表します。 前件に「ただ」が呼応することもあります。 「のみ」はやや硬めの表現なので、会話では「だけ」が使いやすいです。","en":"all one can do is; only; just","ko":"그저 …할 뿐이다; 오직 …뿐이다"},"formation":{"ja":"（ただ＋）動作性の名詞＋あるのみだ / （ただ＋）動詞辞書形＋のみ / （ただ＋）名詞（＋助詞）＋のみ","en":"（ただ＋）動作性の名詞＋あるのみだ / （ただ＋）動詞辞書形＋のみ / （ただ＋）名詞（＋助詞）＋のみ","ko":"（ただ＋）動作性の名詞＋あるのみだ / （ただ＋）動詞辞書形＋のみ / （ただ＋）名詞（＋助詞）＋のみ"},"examples":[{"ja":"ただ前進あるのみだ。","en":"All there is to do is keep moving forward.","ko":"그저 전진할 뿐이다."}],"similar":[]},
  {"id":"d1725293495764","pattern":"ただでさえ〜","core":"ただでさえ〜","blankTarget":"ただでさえ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"普段でさえ良くない事態が起きていることを表します。 後件には「～のに」等の語が呼応することが多く、その場合、後件では普段の状況を超えた状況下における更に良くない事態が述べられます。","en":"even ordinarily; already (before anything else)","ko":"평소에도; 원래도"},"formation":{"ja":"ただでさえ～","en":"ただでさえ～","ko":"ただでさえ～"},"examples":[{"ja":"ただでさえ暗記するのは苦手なのに、英語勉強するなんて厳しい。","en":"I'm already bad at memorizing, so studying English is just too much.","ko":"평소에도 암기하는 것을 못하는데 영어 공부라니 너무 힘들다."}],"similar":[]},
  {"id":"d1725293495702","pattern":"なんという〜／なんと〜／なんて〜","core":"なんという〜","blankTarget":"なんという","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"名詞に接続して、驚きの感情を表します。 良い評価にも悪い評価にも使えます。 「なんということだ／なんてことだ／なんてことか／なんてこった／なんてこったい（这是什么事嘛／怎么回事）」は慣用的に用いられ、物事に対する驚きを表します。","en":"what a...!; how...!","ko":"정말 …이구나; 얼마나 …인지"},"formation":{"ja":"なんという＋名詞＋だ／か／だろう／なのだろう／なんだろう / なんという＋ナ形語幹＋だ／か／だろう／なのだろう／なんだろう / なんと／なんて＋名詞＋なのだろう／なんだろう / なんと／なんて＋ナ形語幹＋なのだろう／なんだろう / なんと／なんて＋イ形＋のだろう／んだろう","en":"なんという＋名詞＋だ／か／だろう／なのだろう／なんだろう / なんという＋ナ形語幹＋だ／か／だろう／なのだろう／なんだろう / なんと／なんて＋名詞＋なのだろう／なんだろう / なんと／なんて＋ナ形語幹＋なのだろう／なんだろう / なんと／なんて＋イ形＋のだろう／んだろう","ko":"なんという＋名詞＋だ／か／だろう／なのだろう／なんだろう / なんという＋ナ形語幹＋だ／か／だろう／なのだろう／なんだろう / なんと／なんて＋名詞＋なのだろう／なんだろう / なんと／なんて＋ナ形語幹＋なのだろう／なんだろう / なんと／なんて＋イ形＋のだろう／んだろう"},"examples":[{"ja":"なんという偶然か。適当に書いた答えが全部当たっていた。","en":"What a coincidence! Every answer I wrote at random turned out to be correct.","ko":"얼마나 우연인지! 아무렇게나 쓴 답이 전부 맞았다."}],"similar":[]},
  {"id":"d1725293495834","pattern":"やれ〜やれ〜","core":"やれ〜やれ〜","blankTarget":"やれ","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"何らかの共通項を持った要素たちの中からいくつかを列挙する一部列挙型の並列助詞です。他の要素の存在も暗示します。 多くの場合、列挙した事物に対する嫌悪感や不快感、敵意などのネガティブなニュアンスが含まれます。 通常は２つの要素を列挙しますが、３つ以上挙げることも可能です。また２つ目の要素は省略することもできます。その場合は「やれ～だのやれ何だの（と）」という慣用的な言い方を用います。","en":"what with... and...; ...and... (listing with annoyance)","ko":"이것도 저것도 …이고 …이고 (못마땅함)"},"formation":{"ja":"やれ＋名詞＋だ、やれ＋名詞＋だと / やれ＋名詞＋だの、やれ＋名詞＋だのと / やれ＋会話文＋だ、やれ＋会話文＋だと / やれ＋会話文＋だの、やれ＋会話文＋だのと","en":"やれ＋名詞＋だ、やれ＋名詞＋だと / やれ＋名詞＋だの、やれ＋名詞＋だのと / やれ＋会話文＋だ、やれ＋会話文＋だと / やれ＋会話文＋だの、やれ＋会話文＋だのと","ko":"やれ＋名詞＋だ、やれ＋名詞＋だと / やれ＋名詞＋だの、やれ＋名詞＋だのと / やれ＋会話文＋だ、やれ＋会話文＋だと / やれ＋会話文＋だの、やれ＋会話文＋だのと"},"examples":[{"ja":"やれ出張だの、やれ会議だのと、ゆっくりする暇もない。","en":"What with business trips and meetings, I have no time to relax.","ko":"출장이다 회의다 해서 느긋할 틈이 없다."}],"similar":[]},
  {"id":"d1725293495655","pattern":"一概に〜ない／一概には〜ない","core":"一概に〜ない","blankTarget":"一概には","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"様々な観点から物事見た結果、複数の評価や捉え方が存在するため、それらをひとまとめにすることはできないことを表します。 「～とは一概に言えない／言い切れない」「一概に～とは言えない／言い切れない」の形が頻出する文型です。 後件には必ず否定表現が伴います。","en":"cannot be generalized; cannot be categorically said","ko":"일률적으로 …할 수 없다; 단정할 수 없다"},"formation":{"ja":"文＋とは一概に～ない / 一概に＋文＋とは～ない","en":"文＋とは一概に～ない / 一概に＋文＋とは～ない","ko":"文＋とは一概に～ない / 一概に＋文＋とは～ない"},"examples":[{"ja":"Ａ案とＢ案に対する賛否が分かれていて、どっちが良いかは一概には決められない。","en":"Opinions on plans A and B are divided, so it is impossible to say definitively which is better.","ko":"A안과 B안에 대한 찬반이 갈려서 어느 쪽이 좋은지 일률적으로 정할 수 없다."}],"similar":[]},
  {"id":"d1725293495654","pattern":"今一〜ない／今一つ〜ない","core":"今一〜ない","blankTarget":"今一","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"後件に否定形を伴い、何かが不足していて物足りないことを表します。 「今一（いまいち）」「今一つ（いまひとつ）」はナ形容詞なので、単独でも用いることができます。例文（７）（８）。 「今一」は「イマイチ」とカタカナで書かれることもあります。","en":"not quite; not entirely; still lacking","ko":"영 미덥지 않다; 한 끗 부족하다"},"formation":{"ja":"今一（いまいち）＋～ない / 今一つ（いまひとつ）＋～ない / 今一／今一つ＋な＋名詞 / ～が今一だ / ～が今一つだ","en":"今一（いまいち）＋～ない / 今一つ（いまひとつ）＋～ない / 今一／今一つ＋な＋名詞 / ～が今一だ / ～が今一つだ","ko":"今一（いまいち）＋～ない / 今一つ（いまひとつ）＋～ない / 今一／今一つ＋な＋名詞 / ～が今一だ / ～が今一つだ"},"examples":[{"ja":"このアプリ今一使い方が分からない。","en":"I don't quite get how to use this app.","ko":"이 앱은 사용법이 영 모르겠다."}],"similar":[]},
  {"id":"d1725293495690","pattern":"滅多に〜ない(めったに〜ない)","core":"滅多に〜ない(めったに〜ない)","blankTarget":"めったに","reading":"","quiz":true,"tag":"general","level":"N1","meaning":{"ja":"発生頻度や回数が非常に少ないことを強調する文型です。","en":"rarely; seldom","ko":"좀처럼 …하지 않다; 드물다"},"formation":{"ja":"滅多に＋動ない形＋ない / ～は滅多にない","en":"滅多に＋動ない形＋ない / ～は滅多にない","ko":"滅多に＋動ない形＋ない / ～は滅多にない"},"examples":[{"ja":"酒は普段めったに飲まない。","en":"I rarely drink alcohol.","ko":"술은 평소에 좀처럼 마시지 않는다."}],"similar":[]}
]);
